/* ============ 插件：停用即持久停用（左侧入口一起消失） ============ */
function __sparklePluginDisabled(id){
  var list=oa.value&&oa.value.disabledPlugins;
  return !!list&&list.indexOf(id)>=0;
}
function __sparkleSetPluginEnabled(id,enabled){
  if(!id)return Promise.resolve();
  var list=(oa.value&&oa.value.disabledPlugins)?oa.value.disabledPlugins.slice():[];
  var has=list.indexOf(id)>=0;
  var next=enabled?(has?list.filter(function(x){return x!==id}):list):(has?list:list.concat([id]));
  return fa({disabledPlugins:next});
}
/** 激活：先从"停用名单"里移掉（主进程会解除禁用），再真正激活 */
function __sparkleActivatePlugin(raw){
  return async function(id){
    try{await __sparkleSetPluginEnabled(id,!0)}catch(e){}
    if(raw)return await raw(id);
  };
}
/** 停用：先停掉运行时，再写进停用名单（重启后也不会再加载，左侧入口立即消失） */
function __sparkleDeactivatePlugin(raw){
  return async function(id){
    try{if(raw)await raw(id)}catch(e){}
    try{await __sparkleSetPluginEnabled(id,!1)}catch(e){}
  };
}
async function __sparkleGrantAll(plugin,allow){
  if(!plugin)return;
  var perms=allow?(plugin.requested||[]).slice():[];
  try{await Va().setGranted(plugin.id,perms)}catch(e){}
}

