var __sparkleLook = { wallpaper: null, mediaPath: null, mediaKind: null, mediaUrl: null, dataUrl: null, missing: !1, fit: 'cover', blur: 0, dim: .18, videoLoop: !0, videoMuted: !0, videoRate: 1, themeId: 'default', accent: '', panelOpacity: .72, editorOpacity: 1 };
function __sparkleParseColor(input){
  var s=String(input==null?'':input).trim();
  var m=/^#([0-9a-fA-F]{3,8})$/.exec(s);
  if(m){
    var h=m[1];
    if(h.length===3)h=h.charAt(0)+h.charAt(0)+h.charAt(1)+h.charAt(1)+h.charAt(2)+h.charAt(2);
    if(h.length<6)return null;
    var r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);
    if(isNaN(r)||isNaN(g)||isNaN(b))return null;
    return {r:r,g:g,b:b};
  }
  m=/^rgba?\(([^)]+)\)$/.exec(s);
  if(m){
    var p=m[1].split(/[,\/\s]+/).filter(function(x){return x!==''});
    if(p.length<3)return null;
    var rr=Math.round(parseFloat(p[0])),gg=Math.round(parseFloat(p[1])),bb=Math.round(parseFloat(p[2]));
    if(isNaN(rr)||isNaN(gg)||isNaN(bb))return null;
    return {r:rr,g:gg,b:bb};
  }
  return null;
}
function __sparkleRgba(c,a){
  var k=Math.max(0,Math.min(1,a));
  return 'rgba('+c.r+','+c.g+','+c.b+','+(Math.round(k*1000)/1000)+')';
}
function __sparkleApplyAppearanceLegacy(state){
  if(state&&typeof state==='object'){
    if('wallpaper' in state)__sparkleLook.wallpaper=state.wallpaper||null;
    if('dataUrl' in state)__sparkleLook.dataUrl=state.dataUrl||null;
    if('missing' in state)__sparkleLook.missing=!!state.missing;
    if(typeof state.panelOpacity==='number'&&isFinite(state.panelOpacity))__sparkleLook.panelOpacity=Math.min(1,Math.max(0,state.panelOpacity));
    if(typeof state.editorOpacity==='number'&&isFinite(state.editorOpacity))__sparkleLook.editorOpacity=Math.min(1,Math.max(0,state.editorOpacity));
  }
  var body=document.body;
  if(!body)return;
  var cs=null;
  try{cs=getComputedStyle(document.documentElement)}catch(e){cs=null}
  function pick(name,fb){var c=cs?__sparkleParseColor(cs.getPropertyValue(name)):null;return c||fb}
  var cBg=pick('--bg',{r:31,g:31,b:31});
  var cElev=pick('--bg-elevated',cBg);
  var cPanel=pick('--bg-panel',cBg);
  var cStatus=pick('--status-bg',cElev);
  var cHover=pick('--hover',{r:42,g:45,b:46});
  var cActive=pick('--active',{r:55,g:55,b:61});
  var pa=__sparkleLook.panelOpacity;
  body.style.setProperty('--bg',__sparkleRgba(cBg,pa));
  body.style.setProperty('--bg-elevated',__sparkleRgba(cElev,pa));
  body.style.setProperty('--bg-panel',__sparkleRgba(cPanel,pa));
  body.style.setProperty('--status-bg',__sparkleRgba(cStatus,pa));
  body.style.setProperty('--hover',__sparkleRgba(cHover,pa));
  body.style.setProperty('--active',__sparkleRgba(cActive,pa));
  /* 编辑器底色跟的是 Monaco 主题里写死的 #1f1f1f，不是应用主题的 --bg */
  body.style.setProperty('--sparkle-editor-bg',__sparkleRgba({r:31,g:31,b:31},__sparkleLook.editorOpacity));
  body.style.backgroundColor='rgb('+cBg.r+','+cBg.g+','+cBg.b+')';
  var has=!!(__sparkleLook.wallpaper&&__sparkleLook.dataUrl);
  body.classList.toggle('sparkle-wallpaper',has);
  if(has)body.style.backgroundImage='url("'+__sparkleLook.dataUrl+'")';
  else body.style.backgroundImage='';
}
function __sparkleLookApi(){return window.sparkle&&window.sparkle.appearance}
