  var hint=__sparkleEl('div','font-size:11.5px;line-height:1.7;color:var(--fg-muted,#6e7681);margin:2px 0 12px');
  hint.textContent='面板不透明度越低，壁纸越明显；编辑器不透明度只影响代码编辑区。快捷键 Ctrl+Alt+B。';
  var foot=__sparkleEl('div','display:flex;justify-content:flex-end');
  var close=__sparkleBtn('关闭','',function(){if(mask.parentNode)mask.parentNode.removeChild(mask)});
  close.style.padding='6px 14px';close.style.fontSize='12px';
  foot.appendChild(close);
  box.appendChild(title);box.appendChild(wallRow);box.appendChild(panelRow);box.appendChild(editorRow);box.appendChild(hint);box.appendChild(foot);
  mask.appendChild(box);
  mask.addEventListener('keydown',function(ev){ev.stopPropagation();if(ev.key==='Escape'){ev.preventDefault();if(mask.parentNode)mask.parentNode.removeChild(mask)}});
