/* ============ AI 助手（手写 Agent）+ 左下角快捷入口 ============ */
var __sparkleAi = {
  built: !1,
  open: !1,
  busy: !1,
  mode: 'hint',
  includeFile: !0,
  allowWrite: !1,
  depth: 'normal',
  phase: '',
  history: [],
  config: null,
  providers: {},
  streamed: !1,
  els: {}
};
var __sparkleAiToolList = [];
var __sparkleAiToolMap = {};

/* ---- 工具注册：以后接 OJ 插件，只要再调一次 __sparkleAiRegisterTool ---- */
function __sparkleAiRegisterTool(def, handler){
  if(!def||!def.function||!def.function.name||typeof handler!=='function')return !1;
  var name=def.function.name;
  __sparkleAiToolMap[name]=handler;
  for(var i=0;i<__sparkleAiToolList.length;i++){
    if(__sparkleAiToolList[i].function.name===name){__sparkleAiToolList[i]=def;return !0}
  }
  __sparkleAiToolList.push(def);
  return !0;
}
function __sparkleAiToolDefs(){return __sparkleAiToolList.slice()}

/* ---- 文本偏移 → Monaco 行列（都从 1 开始） ---- */
function __sparkleAiOffsetToPos(text, offset){
  var line=1, col=1;
  var n=Math.max(0,Math.min(offset,text.length));
  for(var i=0;i<n;i++){
    if(text.charCodeAt(i)===10){line+=1;col=1}
    else col+=1;
  }
  return {line:line,column:col};
}

/* ---- 内置工具 ---- */
__sparkleAiRegisterTool({
  type:'function',
  function:{
    name:'list_dir',
    description:'列出工作区里某个目录下的文件和子目录。path 为空字符串表示工作区根目录。',
    parameters:{type:'object',properties:{path:{type:'string',description:'相对工作区的目录路径，根目录用空字符串'}},required:['path']}
  }
},async function(args){
  var fs=window.sparkle&&window.sparkle.fs;
  if(!fs)return '当前没有可用的文件接口';
  var r=await fs.readDirectory(String(args&&args.path||''));
  var list=(r&&r.entries)||[];
  if(!list.length)return '（空目录）';
  return list.map(function(e){return e.kind==='directory'?e.name+'/':e.name}).join('\n');
});

__sparkleAiRegisterTool({
  type:'function',
  function:{
    name:'read_file',
    description:'读取工作区里一个文本文件的完整内容。改代码之前先用它看清原文。',
    parameters:{type:'object',properties:{path:{type:'string',description:'相对工作区的文件路径'}},required:['path']}
  }
},async function(args){
  var fs=window.sparkle&&window.sparkle.fs;
  if(!fs)return '当前没有可用的文件接口';
  var r=await fs.readFile(String(args&&args.path||''));
  if(r.binary)return '这是二进制文件，不能用文本方式读取。';
  var c=String(r.content||'');
  if(c.length>30000)return c.slice(0,30000)+'\n…（内容太长，已截断到 30000 字符）';
  if(r.truncated)return c+'\n…（文件较大，只读到开头部分）';
  return c;
});

__sparkleAiRegisterTool({
  type:'function',
  function:{
    name:'write_file',
    description:'把整个文件写成给定内容（文件不存在就新建）。只想改一小段时优先用 edit_file。',
    parameters:{type:'object',properties:{
      path:{type:'string',description:'相对工作区的文件路径'},
      content:{type:'string',description:'要写入的完整内容'}
    },required:['path','content']}
  }
},async function(args){
  var p=String(args&&args.path||'');
  var c=String(args&&args.content==null?'':args.content);
  if(!p)return 'path 不能为空';
  var tabs=ho().tabs.value;
  var tab=null;
  for(var i=0;i<tabs.length;i++)if(tabs[i].path===p)tab=tabs[i];
  if(tab){
    ho().setContent(p,c);
    var ok=await ho().saveTab(p);
    return ok?'已写入并保存：'+p:'写入失败：'+p;
  }
  await window.sparkle.fs.saveFile(p,c);
  return '已写入：'+p;
});

__sparkleAiRegisterTool({
  type:'function',
  function:{
    name:'edit_file',
    description:'把文件里的一段代码替换成新的代码。old_text 必须在文件里唯一出现；替换前先用 read_file 确认原文。',
    parameters:{type:'object',properties:{
      path:{type:'string',description:'相对工作区的文件路径'},
      old_text:{type:'string',description:'要被替换的原文（必须唯一匹配）'},
      new_text:{type:'string',description:'替换后的新代码'}
    },required:['path','old_text','new_text']}
  }
},async function(args){
  var p=String(args&&args.path||'');
  var oldText=String(args&&args.old_text==null?'':args.old_text);
  var newText=String(args&&args.new_text==null?'':args.new_text);
  if(!p)return 'path 不能为空';
  if(!oldText)return 'old_text 不能为空';
  var tabs=ho().tabs.value;
  var tab=null;
  for(var i=0;i<tabs.length;i++)if(tabs[i].path===p)tab=tabs[i];
  var content=null;
  if(tab)content=String(tab.content||'');
  else{
    var r=await window.sparkle.fs.readFile(p);
    if(r.binary)return '这是二进制文件，不能改。';
    content=String(r.content||'');
  }
  var at=content.indexOf(oldText);
  if(at<0)return '没有找到 old_text 这段代码。先用 read_file 看清原文（注意空格和缩进要完全一致）。';
  if(content.indexOf(oldText,at+1)>=0)return 'old_text 在文件里出现了多次，请带上更多上下文让它唯一。';
  var next=content.slice(0,at)+newText+content.slice(at+oldText.length);
  if(tab){
    if(ho().activePath.value===p&&Yo&&typeof Yo.applyEdits==='function'){
      var from=__sparkleAiOffsetToPos(content,at);
      var to=__sparkleAiOffsetToPos(content,at+oldText.length);
      try{
        var res=Yo.applyEdits([{startLine:from.line,startColumn:from.column,endLine:to.line,endColumn:to.column,text:newText}]);
        if(res&&res.ok)return '已修改（编辑器里可直接 Ctrl+Z 撤回，别忘了 Ctrl+S 保存）';
      }catch(e){}
    }
    ho().setContent(p,next);
    return '已修改（还没写盘，按 Ctrl+S 保存）';
  }
  await window.sparkle.fs.saveFile(p,next);
  return '已修改并保存到磁盘：'+p;
});

/* ---- 系统提示词 ---- */
function __sparkleAiModeText(){
  var m=__sparkleAi.mode;
  if(m==='hint')return '提示';
  if(m==='solution')return '解法';
  return '代码';
}
function __sparkleAiSystemPrompt(){
  var mode=__sparkleAi.mode;
  var rule='';
  if(mode==='hint')rule='【当前模式：提示】只给思路方向、关键观察、容易踩的坑。不要给完整算法步骤，不要贴完整代码。两三句话点到为止，最多给一个很小的例子。';
  else if(mode==='solution')rule='【当前模式：解法】把算法讲清楚：思路、为什么对、复杂度、边界与坑（溢出、多测、清空、初值、数据范围）。可以给伪代码或关键片段，但不要给可以直接提交的完整程序。';
  else rule='【当前模式：代码】给出完整、可直接编译提交的 C++ 程序，并在代码前用几句话说明思路和复杂度。';
  return [
    '你是 Sparkle IDE 内置的 OI（信息学奥赛）编程助手，服务对象是中国的中学生选手。',
    '用简体中文回答，直接、准确、不说客套话。',
    rule,
    __sparkleAiDepthRule(),
    __sparkleAiLangRule(),
    '',
    '【代码规范】',
    '- C++17，竞赛常用写法；可以用 #include <bits/stdc++.h>（本机预装 MinGW GCC 支持）。',
    '- 注意：数据范围决定开不开 long long、会不会溢出；多组数据要清空；下标越界和初值要检查。',
    '- 不要引入需要联网或特殊平台的库；除非题目要求，不要写 freopen。',
    '- 变量名用英文短名（n, m, a[], f[]）。只在关键处写简短注释。',
    '',
    '【工具】',
    '- 需要看用户代码时用 list_dir / read_file，不要凭空猜测文件内容。',
    __sparkleAi.allowWrite
      ? '- 【可以改代码】允许用 edit_file（替换一段，old_text 必须唯一）或 write_file（整文件覆盖）。优先改用户当前打开的那个文件，改之前先用一句话说清要改哪里、为什么。'
      : '- 【只读模式】用户没有打开「允许改代码」，你没有写文件的工具。不要声称改了文件，只在回答里给代码和建议。',
    '- 改完用一句话说明改了什么。读不到文件就直说读不到。',
    '- 留了 oj_ 开头的工具位给将来的「从 OJ 拉题」插件；现在没有这类工具就不要假装有。'
  ].join('\n');
}
function __sparkleAiDepthRule(){
  var d=__sparkleAi.depth;
  if(d==='fast')return '【思考深度：快】直接给结论，不要展开推理过程，不要列步骤。';
  if(d==='deep')return '【思考深度：深入】先把算法、复杂度、边界都想清楚再动笔；容易错的地方主动说明为什么这样写是对的。';
  return '【思考深度：标准】想清楚再答，但不要写冗长的推理过程。';
}
function __sparkleAiFileContext(){
  if(!__sparkleAi.includeFile)return null;
  var tabs=ho().tabs.value;
  var path=ho().activePath.value;
  var tab=null;
  for(var i=0;i<tabs.length;i++)if(tabs[i].path===path)tab=tabs[i];
  if(!tab||tab.untitled)return null;
  var body=String(tab.content||'');
  if(body.length>14000)body=body.slice(0,14000)+'\n…（已截断）';
  var root='';
  try{var w=ho().workspace.value;root=(w&&w.root)||''}catch(e){}
  return '【用户当前打开的文件】\n路径：'+tab.path+'\n语言：'+tab.language+'\n工作区根目录：'+(root||'（未打开文件夹）')+'\n内容：\n```'+String(tab.language||'')+'\n'+body+'\n```';
}

/* ---- 面板 UI ---- */
function __sparkleAiEl(tag,cls,text){
  var el=document.createElement(tag);
  if(cls)el.className=cls;
  if(text!=null)el.textContent=text;
  return el;
}
function __sparkleAiNote(text){
  var log=__sparkleAi.els.log;
  if(!log)return;
  var d=__sparkleAiEl('div','sparkle-ai-note',text);
  log.appendChild(d);
  log.scrollTop=log.scrollHeight;
  return d;
}
function __sparkleAiAppend(role,text){
  var log=__sparkleAi.els.log;
  if(!log)return null;
  var wrap=__sparkleAiEl('div','sparkle-ai-msg '+role);
  var head=__sparkleAiEl('div','sparkle-ai-msg-head',role==='user'?'我':'AI');
  var body=__sparkleAiEl('div','sparkle-ai-msg-body');
  body.textContent=text||'';
  wrap.appendChild(head);wrap.appendChild(body);
  log.appendChild(wrap);
  log.scrollTop=log.scrollHeight;
  return body;
}
function __sparkleAiRenderMarkdown(el,text){
  el.textContent='';
  var parts=String(text||'').split('```');
  for(var i=0;i<parts.length;i++){
    if(i%2===1){
      var pre=__sparkleAiEl('pre','sparkle-ai-code',parts[i].replace(/^[a-zA-Z0-9+#-]*\n/,''));
      el.appendChild(pre);
    }else if(parts[i]){
      el.appendChild(__sparkleAiEl('div','sparkle-ai-text',parts[i]));
    }
  }
}
/** 输入框占位文字跟着「问法 + 深度」变，让当前状态在打字前就能看见 */
function __sparkleAiSyncPlaceholder(){
  var st=__sparkleAi;
  if(!st.els.input)return;
  var nameMap={hint:'提示',solution:'解法',code:'代码'};
  var depthMap={fast:'快',normal:'标准',deep:'深入'};
  var tipMap={hint:'给点思路就行',solution:'讲清算法和边界',code:'直接给完整程序'};
  st.els.input.placeholder='「'+(nameMap[st.mode]||'提示')+' · '+(depthMap[st.depth]||'标准')
    +'」'+(tipMap[st.mode]||'')+'…（Ctrl+Enter 发送）';
}
function __sparkleAiUpdateChrome(){
  var st=__sparkleAi;
  if(st.els.send){
    st.els.send.textContent=st.busy?'停止':'发送';
    st.els.send.classList.toggle('busy',st.busy);
  }
  if(st.els.model){
    var cfg=st.config||{};
    var p=cfg.provider&&st.providers[cfg.provider]?st.providers[cfg.provider].label:cfg.provider||'';
    st.els.model.textContent=(p?p+' · ':'')+(cfg.model||'未配置');
  }
  function sync(btns,current){
    if(!btns)return;
    for(var k in btns){
      if(Object.prototype.hasOwnProperty.call(btns,k))btns[k].classList.toggle('active',k===current);
    }
  }
  sync(st.els.modeBtns,st.mode);
  sync(st.els.depthBtns,st.depth);
  if(st.els.status)st.els.status.textContent=st.busy?(st.phase||'思考中…'):'';
}
function __sparkleAiBuild(){
  var st=__sparkleAi;
  if(st.built)return;
  var panel=__sparkleAiEl('div','sparkle-ai');
  panel.id='sparkle-ai-panel';
  var head=__sparkleAiEl('div','sparkle-ai-head');
  var title=__sparkleAiEl('div','sparkle-ai-title','AI 助手');
  var model=__sparkleAiEl('div','sparkle-ai-model','');
  var gear=__sparkleBtn('设置','配置接口 / 模型 / 密钥',function(){__sparkleAiSettings()});
  gear.classList.add('sparkle-ai-iconbtn');
  var close=__sparkleBtn('✕','关闭 AI 面板',function(){__sparkleAiToggle(!1)});
  close.classList.add('sparkle-ai-iconbtn');
  head.appendChild(title);head.appendChild(model);head.appendChild(gear);head.appendChild(close);

  function segRow(labelText,items,onPick){
    var row=__sparkleAiEl('div','sparkle-ai-bar');
    row.appendChild(__sparkleAiEl('span','sparkle-ai-bar-label',labelText));
    var btns={};
    items.forEach(function(pair){
      var b=__sparkleBtn(pair[1],pair[2],function(){
        onPick(pair[0]);
        __sparkleAiUpdateChrome();
        __sparkleAiSyncPlaceholder();
      });
      b.classList.add('sparkle-ai-mode');
      btns[pair[0]]=b;
      row.appendChild(b);
    });
    return {row:row,btns:btns};
  }
  var modeSeg=segRow('问法',[
    ['hint','提示','只给思路方向，不给代码'],
    ['solution','解法','讲清算法、复杂度和边界'],
    ['code','代码','直接给完整可提交程序']
  ],function(v){st.mode=v});
  var depthSeg=segRow('深度',[
    ['fast','快','只拆一层，子问题直接作答'],
    ['normal','标准','逐层拆解，最多三层'],
    ['deep','深入','一直拆到原子问题，输出前自检']
  ],function(v){st.depth=v});
  var modeBtns=modeSeg.btns;
  var depthBtns=depthSeg.btns;

  var log=__sparkleAiEl('div','sparkle-ai-log');
  var foot=__sparkleAiEl('div','sparkle-ai-foot');
  var input=__sparkleAiEl('textarea','sparkle-ai-input');
  input.rows=3;
  input.placeholder='问一道题，或者问我你这份代码哪里有问题…（Ctrl+Enter 发送）';
  var row=__sparkleAiEl('div','sparkle-ai-row');
  var label=__sparkleAiEl('label','sparkle-ai-check');
  var cb=document.createElement('input');
  cb.type='checkbox';cb.checked=st.includeFile;
  cb.addEventListener('change',function(){st.includeFile=cb.checked});
  label.appendChild(cb);
  label.appendChild(document.createTextNode(' 带上当前文件'));
  var wLabel=__sparkleAiEl('label','sparkle-ai-check');
  var wCb=document.createElement('input');
  wCb.type='checkbox';wCb.checked=st.allowWrite;
  wCb.title='打开后 AI 才能改文件；改动走编辑器，可以 Ctrl+Z 撤回';
  wCb.addEventListener('change',function(){st.allowWrite=wCb.checked});
  wLabel.appendChild(wCb);
  wLabel.appendChild(document.createTextNode(' 允许改代码'));
  wLabel.title='打开后 AI 才能改文件；改动走编辑器，可以 Ctrl+Z 撤回';
  var status=__sparkleAiEl('span','sparkle-ai-status','');
  var send=__sparkleBtn('发送','',function(){
    if(st.busy){__sparkleAiStop();return}
    __sparkleAiSend();
  });
  send.classList.add('sparkle-ai-send');
  row.appendChild(label);row.appendChild(wLabel);row.appendChild(status);row.appendChild(send);
  foot.appendChild(input);foot.appendChild(row);

  var oiRow=__sparkleAiEl('div','sparkle-ai-bar');
  oiRow.appendChild(__sparkleAiEl('span','sparkle-ai-bar-label','OI'));
  [['review','审代码','找边界、溢出、越界、清空、复杂度'],
   ['complexity','算复杂度','分析时间空间，给卡常方向'],
   ['hack','造 hack','针对当前代码构造能卡掉它的数据']].forEach(function(pair){
    var b=__sparkleBtn(pair[1],pair[2],function(){__sparkleAiQuick(pair[0])});
    b.classList.add('sparkle-ai-mode');
    oiRow.appendChild(b);
  });
  panel.appendChild(head);panel.appendChild(modeSeg.row);panel.appendChild(depthSeg.row);panel.appendChild(oiRow);panel.appendChild(log);panel.appendChild(foot);
  document.body.appendChild(panel);

  st.els.panel=panel;st.els.model=model;st.els.log=log;st.els.input=input;
  st.els.send=send;st.els.status=status;st.els.modeBtns=modeBtns;st.els.depthBtns=depthBtns;
  st.els.close=close;st.els.includeCb=cb;
  st.built=!0;

  input.addEventListener('keydown',function(ev){
    ev.stopPropagation();
    if(ev.key==='Enter'&&(ev.ctrlKey||ev.metaKey)){ev.preventDefault();__sparkleAiSend()}
  });
  input.addEventListener('keyup',function(ev){ev.stopPropagation()});
  var api=window.sparkle&&window.sparkle.ai;
  if(api&&api.onChunk){
    api.onChunk(function(payload){
      if(!payload||!payload.delta)return;
      var body=st.els.streaming;
      if(!body)return;
      st.streamed=!0;
      body.textContent+=payload.delta;
      var logEl=st.els.log;
      if(logEl)logEl.scrollTop=logEl.scrollHeight;
    });
  }
  __sparkleAiUpdateChrome();
  __sparkleAiSyncPlaceholder();
}
/** 面板停在左栏（活动栏右边），替代左侧文件树的位置；比文件树宽出来的部分才挤编辑器 */
function __sparkleAiDockWidth(){
  var panelW=380;
  var side=document.querySelector('.sidebar');
  var sideW=side?Math.round(side.getBoundingClientRect().width):0;
  return Math.max(0,panelW-sideW);
}
function __sparkleAiToggle(force){
  var st=__sparkleAi;
  if(!__sparkleAiEnabled()&&force!==!1){
    window.alert(__sparkleContestActive
      ? '比赛模式进行中，AI 助手已被锁定。结束比赛后即可使用。'
      : 'AI 助手已在「设置 → 内置插件：AI 助手」里停用，重新启用后即可使用。');
    return;
  }
  __sparkleAiBuild();
  var open=typeof force==='boolean'?force:!st.open;
  if(open&&typeof __sparkleOi!=='undefined'&&__sparkleOi&&__sparkleOi.open){
    try{__sparkleOiToggle(!1)}catch(e){}
  }
  if(open&&typeof __sparkleGit!=='undefined'&&__sparkleGit.open){
    try{__sparkleGitToggle(!1)}catch(e){}
  }
  st.open=open;
  st.els.panel.classList.toggle('open',open);
  var mainEl=document.querySelector('main.editor-area');
  if(mainEl)mainEl.style.paddingLeft=open?String(__sparkleAiDockWidth())+'px':'';
  if(open){
    var sbEl=document.querySelector('.status-bar');
    var h=sbEl?Math.round(sbEl.getBoundingClientRect().height):22;
    st.els.panel.style.bottom=(h||22)+'px';
    setTimeout(function(){try{st.els.input.focus()}catch(e){}},30);
  }
}
function __sparkleAiOpen(){__sparkleAiToggle(!0)}

/* ---- 配置 ---- */
async function __sparkleAiLoadConfig(){
  var api=window.sparkle&&window.sparkle.ai;
  var st=__sparkleAi;
  if(!api){st.config={};return}
  try{
    var r=await api.loadConfig();
    if(r){st.config=r.config||{};st.providers=r.providers||{}}
  }catch(e){st.config={}}
  __sparkleAiUpdateChrome();
}
function __sparkleAiSettings(){
  if(document.getElementById('sparkle-ai-settings'))return;
  var st=__sparkleAi;
  var api=window.sparkle&&window.sparkle.ai;
  var cfg=st.config||{};
  var mask=__sparkleEl('div','position:fixed;inset:0;z-index:4100;background:rgba(0,0,0,.5);display:flex;align-items:flex-start;justify-content:center;padding-top:10vh');
  mask.id='sparkle-ai-settings';
  var box=__sparkleEl('div','width:min(620px,92vw);background:var(--bg-panel,#202020);border:1px solid var(--border,#2b2b2b);border-radius:6px;box-shadow:0 16px 48px rgba(0,0,0,.6);padding:16px 18px 12px;color:var(--fg,#ccc);font-size:12.5px');
  var title=__sparkleEl('div','font-size:13px;font-weight:600;margin-bottom:4px');
  title.textContent='AI 接口设置';
  var sub=__sparkleEl('div','font-size:11.5px;color:var(--fg-muted,#6e7681);line-height:1.7;margin-bottom:14px');
  sub.textContent='所有国内厂商都走 OpenAI 兼容的 /chat/completions，只是地址和模型名不同。密钥只存在本机用户目录（明文，别用主账号的 key）。';
  function row(label){
    var r=__sparkleEl('div','display:flex;align-items:center;gap:10px;margin-bottom:10px');
    var n=__sparkleEl('div','flex:0 0 92px;color:var(--fg-dim,#9d9d9d);font-size:12px');
    n.textContent=label;r.appendChild(n);return r;
  }
  function inputEl(css){
    var i=__sparkleEl('input','flex:1 1 auto;min-width:0;font-family:inherit;font-size:12px;padding:5px 8px;border-radius:3px;border:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);color:var(--fg,#ccc);outline:none');
    return i;
  }
  var provRow=row('服务商');
  var sel=__sparkleEl('select','flex:1 1 auto;min-width:0;font-family:inherit;font-size:12px;padding:5px 8px;border-radius:3px;border:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);color:var(--fg,#ccc);outline:none');
  var ids=Object.keys(st.providers);
  if(!ids.length)ids=['deepseek','qwen','glm','kimi','qianfan','siliconflow','ollama','custom'];
  ids.forEach(function(id){
    var o=document.createElement('option');
    o.value=id;
    o.textContent=st.providers[id]?st.providers[id].label:id;
    sel.appendChild(o);
  });
  sel.value=cfg.provider||ids[0];
  provRow.appendChild(sel);
  var hint=__sparkleEl('div','font-size:11px;color:var(--fg-muted,#6e7681);margin:-4px 0 10px 102px');
  hint.textContent=(st.providers[sel.value]&&st.providers[sel.value].hint)||'';
  var urlRow=row('接口地址');var url=inputEl();url.value=cfg.baseUrl||'';urlRow.appendChild(url);
  var modelRow=row('模型');var model=inputEl();model.value=cfg.model||'';modelRow.appendChild(model);
  var keyRow=row('密钥');var key=inputEl();key.type='password';key.value=cfg.apiKey||'';key.placeholder='sk-...';keyRow.appendChild(key);
  var tempRow=row('温度');
  var temp=inputEl();temp.type='number';temp.min='0';temp.max='2';temp.step='0.1';temp.value=String(cfg.temperature==null?0.3:cfg.temperature);temp.style.flex='0 0 90px';
  var tempTip=__sparkleEl('span','font-size:11px;color:var(--fg-muted,#6e7681)','0 更稳，1 更发散；做题建议 0.2~0.4');
  tempRow.appendChild(temp);tempRow.appendChild(tempTip);
  sel.addEventListener('change',function(){
    var p=st.providers[sel.value];
    if(p){url.value=p.baseUrl||'';model.value=p.model||''}
    hint.textContent=(p&&p.hint)||'';
  });
  var foot=__sparkleEl('div','display:flex;align-items:center;gap:8px;justify-content:flex-end;margin-top:6px');
  var save=__sparkleBtn('保存','',async function(){
    var payload={provider:sel.value,baseUrl:url.value.trim(),model:model.value.trim(),apiKey:key.value.trim(),temperature:Number(temp.value)};
    if(!api||!api.saveConfig){save.textContent='当前版本不支持';return}
    try{
      var saved=await api.saveConfig(payload);
      st.config=saved||payload;
      save.textContent='已保存';
      __sparkleAiUpdateChrome();
      setTimeout(function(){save.textContent='保存'},1200);
    }catch(e){save.textContent='保存失败'}
  });
  save.classList.add('sparkle-ai-primary');
  var close=__sparkleBtn('关闭','',function(){if(mask.parentNode)mask.parentNode.removeChild(mask)});
  foot.appendChild(close);foot.appendChild(save);
  box.appendChild(title);box.appendChild(sub);box.appendChild(provRow);box.appendChild(hint);
  box.appendChild(urlRow);box.appendChild(modelRow);box.appendChild(keyRow);box.appendChild(tempRow);box.appendChild(foot);
  mask.appendChild(box);
  mask.addEventListener('keydown',function(ev){ev.stopPropagation();if(ev.key==='Escape'){ev.preventDefault();if(mask.parentNode)mask.parentNode.removeChild(mask)}});
  mask.addEventListener('keyup',function(ev){ev.stopPropagation()});
  mask.addEventListener('mousedown',function(ev){if(ev.target===mask&&mask.parentNode)mask.parentNode.removeChild(mask)});
  document.body.appendChild(mask);
}

/* ---- Agent 主循环：规划 → 分治 → 整合 → 输出 ---- */
var __sparkleAiWriteTools = { write_file: 1, edit_file: 1 };
function __sparkleAiActiveTools(){
  var all=__sparkleAiToolDefs();
  if(__sparkleAi.allowWrite)return all;
  return all.filter(function(d){return !__sparkleAiWriteTools[d.function.name]});
}
function __sparkleAiReadOnlyTools(){
  return __sparkleAiToolDefs().filter(function(d){return !__sparkleAiWriteTools[d.function.name]});
}
function __sparkleAiSetPhase(text){
  __sparkleAi.phase=text||'';
  if(__sparkleAi.els.status)__sparkleAi.els.status.textContent=text||'';
}
function __sparkleAiStep(title,body){
  var log=__sparkleAi.els.log;
  if(!log)return null;
  var wrap=__sparkleAiEl('div','sparkle-ai-step');
  wrap.appendChild(__sparkleAiEl('div','sparkle-ai-step-title',title));
  wrap.appendChild(__sparkleAiEl('div','sparkle-ai-step-body',body||''));
  log.appendChild(wrap);
  log.scrollTop=log.scrollHeight;
  return wrap;
}
function __sparkleAiToolLabel(name,args){
  var p=(args&&(args.path||args.dir))||'';
  if(name==='read_file')return '读取 '+p;
  if(name==='write_file')return '写入 '+p;
  if(name==='edit_file')return '修改 '+p;
  if(name==='list_dir')return '列出 '+(p||'根目录');
  return '调用 '+name;
}
/** 把 HTTP 错误翻成用户能动手解决的话 */
function __sparkleAiExplainError(msg){
  var text=String(msg||'请求失败');
  if(/HTTP 401/.test(text))return text+'\n→ 密钥没填或不正确。点面板右上角「设置」检查 API Key。';
  if(/HTTP 403/.test(text))return text+'\n→ 没有权限，或这个 key 的额度用完了。';
  if(/HTTP 429/.test(text))return text+'\n→ 请求太频繁或额度用尽，等一会儿再试。';
  if(/HTTP 404/.test(text))return text+'\n→ 接口地址不对。检查「设置」里的接口地址（通常要以 /v1 结尾）。';
  if(/HTTP 400/.test(text))return text+'\n→ 参数被拒，最常见的原因是模型名写错了。';
  if(/fetch failed|ENOTFOUND|ECONNREFUSED|ETIMEDOUT/i.test(text))return text+'\n→ 连不上服务器：检查网络，或接口地址是否可访问。';
  return text;
}
async function __sparkleAiRunTool(name,args){
  var fn=__sparkleAiToolMap[name];
  if(!fn)return '没有这个工具：'+name+'（可用：'+Object.keys(__sparkleAiToolMap).join(', ')+'）';
  try{
    var out=await fn(args||{});
    return String(out==null?'（无输出）':out);
  }catch(e){
    return '工具执行失败：'+(e&&e.message?e.message:String(e));
  }
}
function __sparkleAiStop(){
  var st=__sparkleAi;
  var api=window.sparkle&&window.sparkle.ai;
  if(st.abortId&&api&&api.abort)api.abort(st.abortId).catch(function(){});
}
/** 一次请求（不跑工具） */
async function __sparkleAiChat(messages,opts){
  var st=__sparkleAi, api=window.sparkle&&window.sparkle.ai;
  var cfg=st.config||{};
  var id='ai-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);
  st.abortId=id;
  var res;
  try{
    res=await api.chat({
      id:id,
      messages:messages,
      tools:(opts&&opts.tools&&opts.tools.length)?opts.tools:void 0,
      baseUrl:cfg.baseUrl,
      model:cfg.model,
      apiKey:cfg.apiKey,
      temperature:cfg.temperature,
      stream:(opts&&opts.stream===!1)?!1:(cfg.stream!==!1)
    });
  }catch(e){
    res={ok:!1,error:(e&&e.message)?e.message:String(e)};
  }
  st.abortId=null;
  return res||{ok:!1,error:'请求失败'};
}
/** 带工具的一轮或多轮；bubble 为 null 时不显示正文（分治阶段用） */
async function __sparkleAiToolLoop(messages,bubble,tools,maxRounds){
  var st=__sparkleAi;
  var list=tools||[];
  var wrote=[];
  for(var round=0;round<(maxRounds||4);round++){
    st.streamed=!1;
    st.els.streaming=bubble||null;
    var res=await __sparkleAiChat(messages,{tools:list,stream:bubble?void 0:!1});
    st.els.streaming=null;
    if(!res.ok){
      var msg=res.aborted?'[已停止]':'['+__sparkleAiExplainError(res.error||'请求失败')+']';
      if(bubble)bubble.textContent+='\n'+msg;
      else __sparkleAiNote(msg);
      return {ok:!1,content:'',wrote:wrote};
    }
    if(!st.streamed&&res.content&&bubble)bubble.textContent+=res.content;
    var calls=res.toolCalls||[];
    if(!calls.length){
      if(bubble)__sparkleAiRenderMarkdown(bubble,bubble.textContent||'');
      return {ok:!0,content:res.content||'',wrote:wrote};
    }
    messages.push({role:'assistant',content:res.content||null,tool_calls:calls});
    for(var i=0;i<calls.length;i++){
      var call=calls[i];
      var name=(call.function&&call.function.name)||'';
      var args={};
      try{args=JSON.parse(call.function&&call.function.arguments||'{}')}catch(e){args={}}
      if(__sparkleAiWriteTools[name])wrote.push(name+' '+(args.path||''));
      __sparkleAiNote('⚙ '+__sparkleAiToolLabel(name,args));
      var out=await __sparkleAiRunTool(name,args);
      var clipped=String(out);
      if(clipped.length>20000)clipped=clipped.slice(0,20000)+'…（已截断）';
      messages.push({role:'tool',tool_call_id:call.id||('call_'+i),content:clipped});
    }
  }
  if(bubble)__sparkleAiRenderMarkdown(bubble,bubble.textContent||'');
  return {ok:!0,content:'',wrote:wrote};
}
/** 从模型回复里抠出第一段 JSON */
function __sparkleAiParseJson(text){
  var raw=String(text||'').replace(/^[\s\S]*?```(?:json)?/i,'').replace(/```[\s\S]*$/,'');
  var start=raw.indexOf('{');
  var end=raw.lastIndexOf('}');
  if(start<0||end<=start)return null;
  try{return JSON.parse(raw.slice(start,end+1))}catch(e){return null}
}
/** 第一步：判断问题大小 + 给任务规划 */
async function __sparkleAiMakePlan(userText){
  var sys='你是一个任务规划器，只输出 JSON，不要解释，不要 markdown 代码块，不要多余文字。';
  var user=[
    '用户的问题：'+userText,
    '是否附带了用户的代码：'+(__sparkleAi.includeFile?'是':'否'),
    '',
    '输出一个 JSON 对象，字段：',
    'size：只能是 小 / 中 / 大',
    'reason：一句话说明为什么是这个规模',
    'steps：3~5 条中文短句，是这个问题的处理步骤（给人看的）',
    'subtasks：size 为 中 时给 2 条，为 大 时给 2~3 条，每条是一个可以独立分析的小问题；size 为 小 时给空数组',
    '注意：如果这个问题本身已经是一个不能再拆的原子问题（比如"这行为什么报错"），就算 size 是中也要给空数组',
    '',
    '规模参考：',
    '- 小：一两句话就能说清（问语法、看一行代码、问某个函数用法）',
    '- 中：一条主线就能做完（一道需要想算法的题、一处需要定位的 bug）',
    '- 大：需要拆成互相独立的几块（既要读题建模又要给多份实现、大范围重构、多文件改造）'
  ].join('\n');
  var res=await __sparkleAiChat([
    {role:'system',content:sys},
    {role:'user',content:user}
  ],{stream:!1});
  if(!res.ok)return null;
  var plan=__sparkleAiParseJson(res.content);
  if(!plan||typeof plan!=='object')return null;
  var size=String(plan.size||'中');
  if(size.indexOf('大')>=0)size='大';
  else if(size.indexOf('小')>=0)size='小';
  else size='中';
  var steps=Array.isArray(plan.steps)?plan.steps.filter(function(x){return typeof x==='string'&&x.trim()}).slice(0,6):[];
  var subs=Array.isArray(plan.subtasks)?plan.subtasks.filter(function(x){return typeof x==='string'&&x.trim()}).slice(0,3):[];
  if(size==='小')subs=[];
  return {size:size,reason:String(plan.reason||''),steps:steps,subtasks:subs};
}
/**
* 递归分解的预算。
*
* 规则来自需求：已经拆过的子问题，重新评估如果还是"中"以上就继续拆。
*   · 快：最多一层 —— 拆一次，子问题直接作答
*   · 标准：最多三层
*   · 深入：不限层数，但用 maxNodes 兜底，免得一次提问发出几十个请求
* 节点预算是工程约束，不是产品规则：没有它，一个"大"问题能把 API 额度烧光。
*/
var __sparkleAiDecomposeBudget = {
  fast: { maxLevel: 1, maxNodes: 4 },
  normal: { maxLevel: 3, maxNodes: 10 },
  deep: { maxLevel: 99, maxNodes: 16 }
};
function __sparkleAiClip(text, max) {
  var s = String(text == null ? '' : text).replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max) + '…' : s;
}
/**
* 递归求解一个子问题。
*
* level 从 1 开始（首层规划的子任务算 L1）。只有当
*   还有层数 + 还有节点预算 + 再评估的结果仍是中/大 + 确实能拆出子任务
* 这四个条件同时成立时才继续往下递归，否则就地作答。
* 这样"深入"模式也不会对着一个原子问题反复拆。
*/
async function __sparkleAiSolveNode(task, ctx, budget, state, level) {
  state.nodes += 1;
  var plan = null;
  if (level < budget.maxLevel && state.nodes < budget.maxNodes) {
    plan = await __sparkleAiMakePlan(task);
  }
  var canSplit = plan && plan.subtasks.length > 0 && plan.size !== '小' && state.nodes < budget.maxNodes;
  if (canSplit) {
    __sparkleAiNote('↳ L' + level + '「' + __sparkleAiClip(task, 28) + '」仍是' + plan.size + '，继续拆 ' + plan.subtasks.length + ' 块');
    var acc = [];
    for (var i = 0; i < plan.subtasks.length; i += 1) {
      if (state.nodes >= budget.maxNodes) {
        __sparkleAiNote('↳ 已到分解上限（' + budget.maxNodes + ' 个节点），剩下的直接作答');
        break;
      }
      acc = acc.concat(await __sparkleAiSolveNode(plan.subtasks[i], ctx, budget, state, level + 1));
    }
    return acc;
  }
  __sparkleAiSetPhase('② 求解 L' + level + '：' + __sparkleAiClip(task, 18));
  var prior = state.leaves.slice(-4).map(function (x, i) {
    return '[' + (i + 1) + '] ' + x.text;
  }).join('\n');
  var msgs = [{
    role: 'system',
    content: __sparkleAiSystemPrompt() + '\n\n【现在是分治阶段，层级 L' + level + '】只把这个子问题分析清楚，给出结论，不要写最终答案、不要重复整体思路。'
  }];
  if (ctx) msgs.push({ role: 'system', content: ctx });
  msgs.push({
    role: 'user',
    content: '要解决的子问题：' + task + (prior ? ('\n\n已完成的子结论（别重复）：\n' + prior) : '')
  });
  var out = await __sparkleAiToolLoop(msgs, null, __sparkleAiReadOnlyTools(), 3);
  var text = String(out.content || '').trim() || '（这个子任务没有给出结论）';
  state.leaves.push({ task: task, text: text, level: level });
  __sparkleAiStep('② L' + level + ' · ' + __sparkleAiClip(task, 40), text.length > 1500 ? text.slice(0, 1500) + '…' : text);
  return [text];
}

/**
* OI 的三个固定动作。
*
* 自由对话对 OI 选手的价值有限 —— 真正每天要问的就三件事：
* 这份代码哪里有坑、会不会 TLE、什么样的数据能卡掉它。
* 做成按钮，省掉每次重述需求，也保证提问里带上「必须给出行号/数据」这类约束。
*/
var __sparkleAiQuickPrompts={
  review:'【审代码】审这份代码，按这个顺序逐条检查，每条都要指出具体行号和改法：\n'
    +'1) 边界：n=1、空输入、全相同、最大/最小值；\n'
    +'2) 溢出：int 够不够，乘法是否要 long long，累加会不会爆；\n'
    +'3) 越界与未初始化：数组多开 5 格够不够，全局变量是否清零，多组数据有没有重置；\n'
    +'4) 复杂度：会不会 TLE，常数大不大；\n'
    +'5) 读入输出：格式、行尾、多组数据的终止条件。\n'
    +'只列真正有问题的地方，没问题的项直接跳过。',
  complexity:'【算复杂度】分析这份代码的时间和空间复杂度：说明主导项是怎么数出来的（循环层数、每条语句的代价），'
    +'再对照数据范围判断会不会 TLE；如果悬，给出最有效的一到两条卡常方向（换数据结构 / 降常数 / 换 IO）。',
  hack:'【造 hack】针对这份代码的漏洞构造一组能卡掉它的数据：\n'
    +'1) 先用一句话说明它会在什么情况下出错；\n'
    +'2) 给出完整输入（严格按题目输入格式，数据规模要小到能手算）；\n'
    +'3) 给出正确答案，并说明这份代码会输出什么。\n'
    +'数据要能直接粘进对拍器的 data.in。'
};
function __sparkleAiQuick(kind){
  var st=__sparkleAi;
  if(!st.built||!st.els.input)return;
  if(st.busy){__sparkleAiNote('正在回答上一个问题，先停下来再点');return}
  var text=__sparkleAiQuickPrompts[kind];
  if(!text)return;
  var path=ho().activePath.value;
  if(!path){window.alert('先打开一个文件，我要看的正是它');return}
  if(!st.includeFile){
    st.includeFile=!0;
    if(st.els.includeCb)st.els.includeCb.checked=!0;
  }
  st.els.input.value=text;
  __sparkleAiSyncPlaceholder();
  __sparkleAiSend();
}
async function __sparkleAiSend(){
  var st=__sparkleAi, api=window.sparkle&&window.sparkle.ai;
  if(st.busy)return;
  var text=String(st.els.input.value||'').trim();
  if(!text)return;
  if(!api){__sparkleAiNote('这个版本没有 AI 通道，preload 没更新？');return}
  var cfg0=st.config||{};
  var needKey=cfg0.provider!=='ollama';
  if(needKey&&!String(cfg0.apiKey||'').trim()){
    __sparkleAiNote('还没有配置 API 密钥 —— 点右上角「设置」，选一家服务商并填入 key（只存在本机）。');
    return;
  }
  if(!String(cfg0.baseUrl||'').trim()||!String(cfg0.model||'').trim()){
    __sparkleAiNote('接口地址或模型名还是空的，先点「设置」补一下。');
    return;
  }
  st.els.input.value='';
  __sparkleAiAppend('user',text);
  st.history.push({role:'user',content:text});
  if(st.history.length>40)st.history=st.history.slice(-40);
  await __sparkleAiRun();
}
async function __sparkleAiRun(){
  var st=__sparkleAi;
  if(st.busy)return;
  var userText='';
  for(var q=st.history.length-1;q>=0;q--){
    if(st.history[q].role==='user'){userText=st.history[q].content;break}
  }
  st.busy=!0;
  __sparkleAiUpdateChrome();
  try{
    var base=[{role:'system',content:__sparkleAiSystemPrompt()}];
    var ctx=__sparkleAiFileContext();
    if(ctx)base.push({role:'system',content:ctx});
    var hist=st.history.slice(-10);
    for(var h=0;h<hist.length;h++)base.push({role:hist[h].role,content:hist[h].content});

    // ---- 1. 判断问题大小 ----
    var depth=st.depth||'normal';
    var maxRounds=depth==='fast'?2:(depth==='deep'?5:4);
    var budget=__sparkleAiDecomposeBudget[depth]||__sparkleAiDecomposeBudget.normal;
    __sparkleAiSetPhase('① 判断问题规模…');
    var plan=await __sparkleAiMakePlan(userText);
    if(plan){
      var lines=[];
      if(plan.reason)lines.push(plan.reason);
      for(var si=0;si<plan.steps.length;si++)lines.push((si+1)+'. '+plan.steps[si]);
      if(plan.subtasks.length)lines.push('（拆成 '+plan.subtasks.length+' 个子任务分别处理）');
      __sparkleAiStep('① 任务规划 · 规模：'+plan.size,lines.join('\n'));
    }else{
      __sparkleAiStep('① 任务规划','（这次没拿到结构化计划，直接按中等问题处理）');
    }

    // ---- 2. 分治（递归：拆完的子问题若还是中/大，继续往下拆） ----
    var results=[];
    // 深入模式：中等以上的问题强制拆两块（规划器没给就补两条固定的分析维度）
    if(depth==='deep'&&plan&&!plan.subtasks.length&&plan.size!=='小'){
      plan.subtasks=['把解法的思路与正确性讲清楚（为什么不会漏、不会错）','列出这道题的边界与坑，并检查实现会不会踩'];
      __sparkleAiNote('深入模式：规划器没有拆分子任务，已按「正确性 / 边界」拆成 2 块');
    }
    if(plan&&plan.subtasks.length&&plan.size!=='小'){
      var state={nodes:0,leaves:[]};
      for(var k=0;k<plan.subtasks.length;k++){
        if(state.nodes>=budget.maxNodes){
          __sparkleAiNote('↳ 已到分解上限（'+budget.maxNodes+' 个节点），其余子任务跳过');
          break;
        }
        await __sparkleAiSolveNode(plan.subtasks[k],ctx,budget,state,1);
      }
      results=state.leaves.map(function(x){return x.text});
      __sparkleAiNote('分治完成：'+results.length+' 个叶子结论（节点上限 '+budget.maxNodes+'，层数上限 '+(budget.maxLevel>50?'不限':budget.maxLevel)+'）');
    }

    // ---- 3. 整合 + 4. 输出 ----
    __sparkleAiSetPhase('③④ 整合与输出…');
    var finalMsgs=base.slice();
    if(results.length){
      // 插在最后一条 user 之前：有些接口不接受 system 排在 user 后面
      finalMsgs.splice(Math.max(0,finalMsgs.length-1),0,{
        role:'system',
        content:'【分治阶段的结论，供你整合，不要照抄，也不要提「子任务」这种内部说法】\n\n'
          +results.map(function(r,ri){return '【第 '+(ri+1)+' 块】\n'+r}).join('\n\n')
          +'\n\n请把这些结论整合成一个连贯的最终答案，严格遵守当前模式的规则。'
      });
    }
    var bubble=__sparkleAiAppend('assistant','');
    if(depth==='deep'){
      finalMsgs.splice(Math.max(0,finalMsgs.length-1),0,{
        role:'system',
        content:'【输出前自检】检查三件事并融入答案（不要单独列一节）：1) 数据范围会不会溢出；2) 多组数据有没有清空；3) 边界（n=1、空输入、最大值）会不会出错。'
      });
    }
    var out=await __sparkleAiToolLoop(finalMsgs,bubble,__sparkleAiActiveTools(),maxRounds);
    var finalText=String(out.content||'');
    if(out.wrote.length){
      __sparkleAiNote('✎ 已修改：'+out.wrote.join('、')+'（在编辑器里按 Ctrl+Z 可以撤回）');
      finalText+= '\n\n（已修改：'+out.wrote.join('、')+'）';
    }
    if(finalText.trim())st.history.push({role:'assistant',content:finalText});
  }catch(e){
    __sparkleAiNote('出错了：'+((e&&e.message)?e.message:String(e)));
  }finally{
    st.busy=!1;
    st.abortId=null;
    st.els.streaming=null;
    __sparkleAiSetPhase('');
    __sparkleAiUpdateChrome();
  }
}

