    fontFamily:String(__sparkleGet('editorFontFamily')),
    fontLigatures:!!__sparkleGet('fontLigatures'),
    tabSize:Number(__sparkleGet('tabSize'))||4,
    insertSpaces:!!__sparkleGet('insertSpaces'),
    detectIndentation:!1,
