function __sparkleOiApplyLayout(open){
  var mainEl=document.querySelector('main.editor-area');
  var side=document.querySelector('.sidebar');
  var sideW=side?Math.round(side.getBoundingClientRect().width):0;
  var width=sideW||300;
  var panel=__sparkleOi.els.panel;
  if(panel)panel.style.width=width+'px';
  if(open){
    if(side)side.style.display='none';
    // 侧栏藏起来后它的宽度会被编辑器吃掉，所以主区留出等宽的 padding，
    // 效果就是"面板顶替了文件树的位置"，编辑器一点没变小
    if(mainEl)mainEl.style.paddingLeft=width+'px';
  }else{
    if(side)side.style.display='';
    if(mainEl)mainEl.style.paddingLeft='';
  }
}
