async function __sparkleOiLoadContests(){
  var api=__sparkleOiApi();
  if(!api||!api.contests){__sparkleOiNote('比赛列表通道没接上','err');return}
  var src=__sparkleOi.els.contestSource.value;
  var box=__sparkleOi.els.contestBox;
  if(!box)return;
  box.textContent='';
  box.appendChild(__sparkleAiEl('div','oi-hint','正在拉取 '+__sparkleOiSiteName(src)+' 的比赛…'));
  var r=null;
  try{
    r=await api.contests({source:src});
  }catch(e){
    r={ok:!1,error:(e&&e.message)||String(e)};
  }
  box.textContent='';
  if(!r||!r.ok){
    box.appendChild(__sparkleAiEl('div','oi-hint',(r&&r.error)||'拉取失败'));
    return;
  }
  if(!r.contests||!r.contests.length){
    box.appendChild(__sparkleAiEl('div','oi-hint','最近没有正在或即将开始的比赛'));
    return;
  }
  r.contests.forEach(function(contest){
    var row=__sparkleAiEl('div','oi-contest-row');
    var meta=__sparkleAiEl('div','oi-contest-meta');
    meta.appendChild(__sparkleAiEl('div','oi-contest-name',contest.name));
    var sub=__sparkleOiWhen(contest.startTime);
    if(contest.durationSec)sub+=' · '+Math.round(contest.durationSec/60)+' 分钟';
    if(contest.phase==='CODING')sub+=' · 进行中';
    meta.appendChild(__sparkleAiEl('div','oi-hint',sub));
    row.appendChild(meta);
    var joinBtn=__sparkleOiBtn('报名','在 IDE 里报名这场比赛',function(){__sparkleOiJoinContest(src,contest,joinBtn)});
    row.appendChild(joinBtn);
    var btn=__sparkleOiBtn('导入','下载整场题目',function(){__sparkleOiImportContest(src,contest,btn)});
    row.appendChild(btn);
    box.appendChild(row);
  });
}

async function __sparkleOiJoinContest(src,contest,btn){
  var api=__sparkleOiApi();
  if(!api||!api.join){__sparkleOiNote('报名通道没接上','err');return}
  var label=contest.name||String(contest.id);
  if(btn){btn.disabled=!0;btn.textContent='报名中'}
  __sparkleOiNote('正在报名《'+label+'》…');
  var r=null;
  try{
    r=await api.join({site:src,contestId:String(contest.id)});
  }catch(e){
    r={ok:!1,error:(e&&e.message)||String(e)};
  }
  if(btn){btn.disabled=!1;btn.textContent='报名'}
  if(r&&r.ok&&r.window){
    __sparkleOiNote(r.message||'已打开报名页');
    return;
  }
  if(!r||!r.ok){
    __sparkleOiNote((r&&r.error)||'报名失败','err');
    if(r&&r.needLogin)__sparkleOiNote('先点上面「提交」区里的「登录 / 检查登录」','err');
    return;
  }
  if(r.already){
    __sparkleOiNote('已经报名过了：'+label,'ok');
    if(btn)btn.textContent='已报名';
    return;
  }
  __sparkleOiNote('报名成功：'+label,'ok');
  if(btn)btn.textContent='已报名';
}

async function __sparkleOiImportContest(src,contest,btn){
  var api=__sparkleOiApi();
  if(!api||!api.importContest){__sparkleOiNote('比赛导入通道没接上','err');return}
  var label=contest.name||contest.id;
  if(btn){btn.disabled=!0;btn.textContent='导入中'}
  __sparkleOiNote('正在导入《'+label+'》…');
  var r=null;
  try{
    r=await api.importContest({site:src,contestId:String(contest.id)});
  }catch(e){
    r={ok:!1,error:(e&&e.message)||String(e)};
  }
  if(btn){btn.disabled=!1;btn.textContent='导入'}
  if(!r||!r.ok){
    __sparkleOiNote((r&&r.error)||'导入失败','err');
    return;
  }
  var list=(r.imported||[]).map(function(item){
    return {pid:item.pid,dir:item.dir,title:item.title,code:item.code};
  });
  if(list.length){
    __sparkleContestProblems=list;
    __sparkleOiRenderContestList();
    try{await ho().loadDirectory(String(r.contestId||list[0].dir))}catch(e){}
    if(btn&&btn.parentNode&&!btn.parentNode.querySelector('.oi-timer-btn')){
      var timerBtn=__sparkleOiBtn('开始计时','用刚导入的这几道题开一场 120 分钟的比赛（AI 锁定）',function(){__sparkleContestBegin(120)});
      timerBtn.classList.add('oi-timer-btn');
      btn.parentNode.appendChild(timerBtn);
    }
  }
  var message='《'+(r.name||label)+'》：导入 '+list.length+' 题';
  if((r.failed||[]).length)message+='，失败 '+(r.failed||[]).length+' 题';
  __sparkleOiNote(message,(r.failed||[]).length?'err':'ok');
}

/* ---- AI 翻译题面 ---- */
async function __sparkleOiTranslate(){
  var p=__sparkleOi.problem;
  if(!p||!p.dir){__sparkleOiNote('先导入一道题','err');return}
  if(!__sparkleAiEnabled()){__sparkleOiNote('AI 助手已停用，翻译用不了','err');return}
  var mdPath=__sparkleOiJoin(p.dir,'题目.md');
  var text='';
  try{
    var file=await window.sparkle.fs.readFile(mdPath);
    text=String((file&&file.content)||'');
  }catch(e){}
  if(!text.trim()){__sparkleOiNote('读不到 '+mdPath,'err');return}
  __sparkleOiNote('正在翻译题面（用当前 AI 配置）…');
  var res=await __sparkleAiChat([
    {role:'system',content:'你是 OI 题目翻译。把用户给的题面完整翻译成简体中文，输出 Markdown。要求：保留全部公式、变量名、数据范围、样例和限制；术语用竞赛常用译法；不要解释、不要总结、不要添加原文没有的内容。'},
    {role:'user',content:text.slice(0,24000)}
  ],{stream:!1,tools:[]});
  if(!res||!res.ok){
    __sparkleOiNote('翻译失败：'+__sparkleAiExplainError((res&&res.error)||''),'err');
    return;
  }
  var out=String(res.content||'').trim();
  if(!out){__sparkleOiNote('AI 返回了空内容','err');return}
  var target=__sparkleOiJoin(p.dir,'题目.中文.md');
  try{
    await window.sparkle.fs.saveFile(target,'# '+(p.title||p.pid||'题目')+'（中文）\n\n> 由 AI 翻译，仅供理解题意；有冲突以原文为准。\n\n'+out+'\n');
  }catch(e){
    __sparkleOiNote('写文件失败：'+(e&&e.message||e),'err');
    return;
  }
  __sparkleOiNote('已翻译 → '+target,'ok');
  try{
    __sparkleOiEnsurePanes(2);
    var panes=as.value;
    var right=panes[panes.length-1];
    if(right){ls(right.id);Zse(target)}
    var left=as.value[0];
    if(left)ls(left.id);
  }catch(e){}
}

/* ============ Git 插件（独立左栏面板） ============ */
var __sparkleGit = {
  built: !1,
  open: !1,
  refreshing: !1,
  els: {}
};
function __sparkleGitEnabled(){
  var list=(oa.value&&oa.value.disabledPlugins)||[];
  return list.indexOf('builtin.git')<0;
}
function __sparkleGitApi(){return window.sparkle&&window.sparkle.git}
function __sparkleGitNote(text,kind){
  var box=__sparkleGit.els.status;
  if(!box)return;
  box.textContent=text||'';
  box.className='oi-status'+(kind?(' '+kind):'');
}
async function __sparkleGitCall(action,extra){
  var api=__sparkleGitApi();
  if(!api)return{ok:!1,error:'Git 接口没就绪'};
  var payload={action:action};
  if(extra)for(var k in extra)payload[k]=extra[k];
  try{return await api.exec(payload)}
  catch(e){return{ok:!1,error:String((e&&e.message)||e)}}
}

function __sparkleGitBuildPanel(){
  var st=__sparkleGit;
  if(st.built)return;
  var panel=__sparkleAiEl('aside','oi-panel git-panel');
  panel.id='sparkle-git-panel';

  var head=__sparkleAiEl('div','oi-panel-head');
  head.appendChild(__sparkleAiEl('span','oi-panel-title','Git'));
  var badge=__sparkleAiEl('span','git-badge','—');
  st.els.badge=badge;
  head.appendChild(badge);
  var close=__sparkleBtn('✕','关闭（Ctrl+Alt+G）',function(){__sparkleGitToggle(!1)});
  close.classList.add('oi-mini');
  head.appendChild(close);

  var scroll=__sparkleAiEl('div','oi-scroll');

  /* 仓库 */
  var secRepo=__sparkleOiSec('仓库','工作区根目录就是仓库根目录。');
  secRepo.appendChild(__sparkleOiRow(
    __sparkleOiBtn('刷新','重新读取状态、分支与历史',function(){__sparkleGitRefresh()}),
    __sparkleOiBtn('初始化','git init',async function(){
      var r=await __sparkleGitCall('init');
      __sparkleGitNote(r.ok?'已初始化仓库':(r.error||'初始化失败'),r.ok?'ok':'err');
      __sparkleGitRefresh();
    })
  ));
  var repoInfo=__sparkleAiEl('div','oi-result');
  st.els.repo=repoInfo;
  secRepo.appendChild(repoInfo);
  scroll.appendChild(secRepo);

  /* 分支 */
  var secBranch=__sparkleOiSec('分支','切换本地分支。新建分支请先在本机终端里 git switch -c。');
  var branchSel=__sparkleOiSelect([['','（还没有分支）']],'');
  branchSel.style.flex='1 1 auto';
  branchSel.style.minWidth='0';
  st.els.branch=branchSel;
  secBranch.appendChild(__sparkleOiRow(branchSel,
    __sparkleOiBtn('切换','git checkout <分支>',async function(){
      var name=branchSel.value;
      if(!name)return;
      __sparkleGitNote('正在切换…');
      var r=await __sparkleGitCall('checkout',{branch:name});
      __sparkleGitNote(r.ok?('已切换到 '+name):(r.error||'切换失败'),r.ok?'ok':'err');
      __sparkleGitRefresh();
    })
  ));
  scroll.appendChild(secBranch);

  /* 改动 + 提交 */
  var secChange=__sparkleOiSec('改动','提交 = git add -A + git commit。');
  var changes=__sparkleAiEl('div','oi-result git-changes');
  st.els.changes=changes;
  secChange.appendChild(changes);
  var msg=__sparkleOiInput('','提交信息');
  msg.style.flex='1 1 auto';
  msg.style.minWidth='0';
  msg.addEventListener('keydown',function(ev){
    if(ev.key==='Enter'){ev.preventDefault();__sparkleGitCommit()}
  });
  st.els.msg=msg;
  secChange.appendChild(__sparkleOiRow(msg,
    __sparkleOiBtn('提交','暂存全部改动并提交（回车也行）',function(){__sparkleGitCommit()})
  ));
  var diffBox=__sparkleAiEl('pre','git-diff');
  diffBox.style.display='none';
  st.els.diff=diffBox;
  secChange.appendChild(__sparkleOiRow(
    __sparkleOiBtn('diff --stat','看未暂存改动的规模',async function(){
      if(diffBox.style.display!=='none'){diffBox.style.display='none';return}
      var r=await __sparkleGitCall('diff');
      if(!r.ok){__sparkleGitNote(r.error||'读不到 diff','err');return}
      diffBox.textContent=r.text;
      diffBox.style.display='';
    })
  ));
  secChange.appendChild(diffBox);
  scroll.appendChild(secChange);

  /* 远端 */
  var secRemote=__sparkleOiSec('远端','先在终端配好 remote 和凭据。拉取用 --ff-only，不会自动 merge。');
  secRemote.appendChild(__sparkleOiRow(
    __sparkleOiBtn('拉取','git pull --ff-only',function(){__sparkleGitRemote('pull')}),
    __sparkleOiBtn('推送','git push',function(){__sparkleGitRemote('push')}),
    __sparkleOiBtn('抓取','git fetch --prune',function(){__sparkleGitRemote('fetch')})
  ));
  var remoteInfo=__sparkleAiEl('div','oi-result git-remote');
  st.els.remote=remoteInfo;
  secRemote.appendChild(remoteInfo);
  scroll.appendChild(secRemote);

  /* 历史 */
  var secLog=__sparkleOiSec('历史','最近 30 条提交。');
  var logBox=__sparkleAiEl('div','oi-result git-log');
  st.els.log=logBox;
  secLog.appendChild(logBox);
  scroll.appendChild(secLog);

  var status=__sparkleAiEl('div','oi-status','');
  st.els.status=status;

  panel.appendChild(head);
  panel.appendChild(scroll);
  panel.appendChild(status);
  document.body.appendChild(panel);
  st.els.panel=panel;
  st.built=!0;
}

async function __sparkleGitRefresh(){
  var st=__sparkleGit;
  if(!st.built||st.refreshing)return;
  st.refreshing=!0;
  try{
    if(st.els.repo)st.els.repo.textContent='读取中…';
    var res=await Promise.all([
      __sparkleGitCall('status'),
      __sparkleGitCall('branches'),
      __sparkleGitCall('log')
    ]);
    var r=res[0],br=res[1],lg=res[2];

    if(!r||!r.ok){
      var why=(r&&r.error)||'读不到 git 状态';
      if(st.els.repo)st.els.repo.textContent=why;
      if(st.els.changes)st.els.changes.textContent='';
      if(st.els.log)st.els.log.textContent='';
      if(st.els.badge)st.els.badge.textContent='—';
      return;
    }

    if(st.els.badge)st.els.badge.textContent=r.isRepo?(r.branch||'空仓库'):'未初始化';

    if(st.els.repo){
      st.els.repo.textContent='';
      if(r.isRepo){
        st.els.repo.appendChild(__sparkleAiEl('div','oi-hint','分支 '+(r.branch||'（空仓库）')+' · 改动 '+(r.changes||0)+' 个文件'));
      }else{
        st.els.repo.appendChild(__sparkleAiEl('div','oi-hint','这个目录还不是 git 仓库，点「初始化」。'));
      }
      if(r.version)st.els.repo.appendChild(__sparkleAiEl('div','oi-hint dim',r.version));
    }

    if(st.els.changes){
      st.els.changes.textContent='';
      var entries=r.entries||[];
      if(!entries.length){
        st.els.changes.appendChild(__sparkleAiEl('div','oi-hint','工作区是干净的。'));
      }else{
        entries.slice(0,200).forEach(function(e){
          var row=__sparkleAiEl('div','git-file');
          var code=__sparkleAiEl('span','git-file-code '+__sparkleGitCodeClass(e.code),e.code||'?');
          row.appendChild(code);
          row.appendChild(__sparkleAiEl('span','git-file-path',e.path||''));
          st.els.changes.appendChild(row);
        });
      }
    }

    if(st.els.branch){
      var sel=st.els.branch;
      var cur=(br&&br.ok&&br.current)||r.branch||'';
      sel.textContent='';
      var names=(br&&br.ok&&br.branches)||[];
      if(!names.length){
        var only=document.createElement('option');
        only.value='';only.textContent=r.isRepo?'（还没有提交）':'（不是仓库）';
        sel.appendChild(only);
      }else{
        names.forEach(function(name){
          var o=document.createElement('option');
          o.value=name;o.textContent=name;
          sel.appendChild(o);
        });
        sel.value=names.indexOf(cur)>=0?cur:names[0];
      }
    }

    if(st.els.log){
      st.els.log.textContent='';
      var lines=(lg&&lg.ok&&lg.entries)||[];
      if(!lines.length){
        st.els.log.appendChild(__sparkleAiEl('div','oi-hint',(lg&&lg.error)||'还没有任何提交。'));
      }else{
        lines.forEach(function(line){
          var row=__sparkleAiEl('div','git-commit');
          var sp=line.indexOf(' ');
          if(sp>0){
            row.appendChild(__sparkleAiEl('span','git-hash',line.slice(0,sp)));
            row.appendChild(__sparkleAiEl('span','git-msg',line.slice(sp+1)));
          }else{
            row.appendChild(__sparkleAiEl('span','git-msg',line));
          }
          st.els.log.appendChild(row);
        });
      }
    }
  }catch(e){
    if(st.els.repo)st.els.repo.textContent='读 git 状态失败：'+((e&&e.message)||e);
  }finally{
    st.refreshing=!1;
  }
}

function __sparkleGitCodeClass(code){
  var c=String(code||'');
  if(c.indexOf('A')>=0||c.indexOf('?')>=0)return 'add';
  if(c.indexOf('D')>=0)return 'del';
  if(c.indexOf('M')>=0||c.indexOf('R')>=0)return 'mod';
  return 'other';
}

async function __sparkleGitCommit(){
  var st=__sparkleGit;
  var msg=st.els.msg?String(st.els.msg.value||'').trim():'';
  if(!msg){
    __sparkleGitNote('先写提交信息','err');
    if(st.els.msg)st.els.msg.focus();
    return;
  }
  __sparkleGitNote('正在提交…');
  var r=await __sparkleGitCall('commit',{message:msg});
  __sparkleGitNote(r.ok?'已提交':(r.error||'提交失败'),r.ok?'ok':'err');
  if(r.ok&&st.els.msg)st.els.msg.value='';
  __sparkleGitRefresh();
}

async function __sparkleGitRemote(action){
  var st=__sparkleGit;
  var label={pull:'拉取',push:'推送',fetch:'抓取'}[action]||action;
  __sparkleGitNote('正在'+label+'…');
  var r=await __sparkleGitCall(action);
  if(st.els.remote){
    st.els.remote.textContent='';
    st.els.remote.appendChild(__sparkleAiEl('div','oi-hint',r.ok?String(r.message||(label+'完成')):(r.error||(label+'失败'))));
  }
  __sparkleGitNote(r.ok?(label+'完成'):(r.error||(label+'失败')),r.ok?'ok':'err');
  if(r.ok)__sparkleGitRefresh();
}

function __sparkleGitApplyLayout(open){
  var mainEl=document.querySelector('main.editor-area');
  var side=document.querySelector('.sidebar');
  var width=side?Math.round(side.getBoundingClientRect().width):0;
  var w=width||300;
  var panel=__sparkleGit.els.panel;
  if(panel)panel.style.width=w+'px';
  if(open){
    if(side)side.style.display='none';
    if(mainEl)mainEl.style.paddingLeft=w+'px';
  }else{
    if(side)side.style.display='';
    if(mainEl)mainEl.style.paddingLeft='';
  }
}

function __sparkleGitToggle(force){
  var st=__sparkleGit;
  if(!__sparkleGitEnabled()&&force!==!1){
    window.alert('Git 面板已在「设置 → 内置插件」里停用，重新启用后即可使用。');
    return;
  }
  __sparkleGitBuildPanel();
  var open=typeof force==='boolean'?force:!st.open;
  if(open){
    try{if(typeof __sparkleOi!=='undefined'&&__sparkleOi.open)__sparkleOiToggle(!1)}catch(e){}
    try{if(typeof __sparkleAi!=='undefined'&&__sparkleAi.open)__sparkleAiToggle(!1)}catch(e){}
  }
  st.open=open;
  st.els.panel.classList.toggle('open',open);
  try{document.body.classList.toggle('sp-git-open',open)}catch(e){}
  __sparkleGitApplyLayout(open);
  if(open){
    var sb=document.querySelector('.status-bar');
    var h=sb?Math.round(sb.getBoundingClientRect().height):22;
    st.els.panel.style.bottom=(h||22)+'px';
    __sparkleGitRefresh();
  }
}

/** 活动栏「Git」图标：只开左栏面板，不切换主区域视图 */
function __sparkleGitFromActivity(){
  try{__sparkleGitToggle(!0)}catch(e){console.error('打开 Git 面板失败：',e)}
}

/** 命令面板用：打开面板并把光标放到提交信息里 */
function __sparkleGitCommitPrompt(){
  __sparkleGitToggle(!0);
  setTimeout(function(){
    try{__sparkleGit.els.msg.focus()}catch(e){}
  },60);
}

window.addEventListener('keydown',function(ev){
  if((ev.ctrlKey||ev.metaKey)&&ev.altKey&&!ev.shiftKey&&(ev.key==='G'||ev.key==='g')){
    ev.preventDefault();
    __sparkleGitToggle();
  }
});

/* ============ 插件用 config 能力改了设置：同步到界面 ============ */
(function(){
  try{
    var api=window.sparkle&&window.sparkle.settings;
    if(!api||typeof api.onChanged!=='function')return;
    api.onChanged(function(next){
      if(!next)return;
      try{
        var clean=aa(next);
        oa.value=clean;
        la(clean);
      }catch(e){console.error('应用插件改的设置失败：',e)}
    });
  }catch(e){}
})();



/* ============================================================================
 * Sparkle IDE 1.1.1 —— 背景媒体 / 主题自定义 / OI-Wiki 速查 / C++ 标准切换
 * ----------------------------------------------------------------------------
 * 这一段是**追加**到打包产物末尾的扩展代码，刻意全部用 __sparkle 前缀，
 * 并且不删改原有函数：同名函数声明在模块作用域里"后者覆盖前者"，
 * 所以下面重新声明的 __sparkleApplyAppearance / __sparkleAppearanceDialog /
 * __sparkleBuildConfigDialog 会自动接管所有调用点，旧实现原样保留做兜底。
 * ========================================================================== */

/* ======================= 1. 强调色（主题复用应用自带的那套） ======================= */

/*
 * 主题不在这里另起炉灶：应用本身已经有「设置 → 背景」里的四套深色预设
 * （dark / black / navy / warm），由 la() → une() 把变量写到 documentElement。
 * 再搞一套 themeId 只会互相覆盖，所以这里只额外管一个 --accent：
 * 它不在主题变量表里，写上去之后换主题也不会被清掉。
 */
function __sparkleShiftHex(hex, delta) {
  var m = /^#([0-9a-fA-F]{6})$/.exec(String(hex || ''));
  if (!m) return hex;
  var n = parseInt(m[1], 16);
  var r = Math.max(0, Math.min(255, (n >> 16) + delta));
  var g = Math.max(0, Math.min(255, ((n >> 8) & 255) + delta));
  var b = Math.max(0, Math.min(255, (n & 255) + delta));
  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

var __sparkleAccentApplied = '';

function __sparkleApplyAccent(state) {
  var accent = (state && state.accent) || '';
  if (accent === __sparkleAccentApplied) return;
  __sparkleAccentApplied = accent;
  var root = document.documentElement;
  if (!accent) {
    root.style.removeProperty('--accent');
    root.style.removeProperty('--accent-hover');
    return;
  }
  root.style.setProperty('--accent', accent);
  root.style.setProperty('--accent-hover', __sparkleShiftHex(accent, -18));
}

/* ======================= 2. 背景层（图片 / 视频） ======================= */

var __sparkleBg = { root: null, stage: null, img: null, video: null, tile: null, dim: null, key: '', pendingPlay: false };

function __sparkleBgLayer() {
  if (__sparkleBg.root && __sparkleBg.root.isConnected) return __sparkleBg;
  var root = document.createElement('div');
  root.id = 'sparkle-bg-layer';
  root.setAttribute('aria-hidden', 'true');
  /* z-index:-1 让它待在 body 内容之下；配合 body 背景透明就能透出来 */
  root.style.cssText = 'position:fixed;inset:0;z-index:-1;overflow:hidden;pointer-events:none;background:#000;display:none';
  var stage = document.createElement('div');
  stage.style.cssText = 'position:absolute;inset:0;transform-origin:center center;will-change:transform,filter';

  var img = document.createElement('img');
  img.alt = '';
  img.decoding = 'async';
  img.draggable = false;
  img.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;display:none';

  var video = document.createElement('video');
  video.muted = true;
  video.loop = true;
  video.autoplay = true;
  video.playsInline = true;
  video.setAttribute('playsinline', '');
  video.setAttribute('muted', '');
  video.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;display:none;background:#000';

  var tile = document.createElement('div');
  tile.style.cssText = 'position:absolute;inset:0;background-repeat:repeat;background-position:left top;display:none';

  var dim = document.createElement('div');
  dim.style.cssText = 'position:absolute;inset:0;background:#000;opacity:0;pointer-events:none;transition:opacity .18s linear';

  stage.appendChild(img);
  stage.appendChild(video);
  stage.appendChild(tile);
  root.appendChild(stage);
  root.appendChild(dim);
  document.body.insertBefore(root, document.body.firstChild);

  /* 自动播放被策略拦住时，用户第一次点窗口就补上 —— 静音视频通常不会拦，但不能假设 */
  root.addEventListener('click', function () {
    if (__sparkleBg.video && __sparkleBg.video.style.display !== 'none') {
      try { __sparkleBg.video.play().catch(function () {}) } catch (e) {}
    }
  });

  __sparkleBg.root = root;
  __sparkleBg.stage = stage;
  __sparkleBg.img = img;
  __sparkleBg.video = video;
  __sparkleBg.tile = tile;
  __sparkleBg.dim = dim;
  return __sparkleBg;
}

/**
 * 把背景状态落到 DOM。
 *
 * 只有 mediaUrl 变化时才重新赋值 src（拖模糊/暗化滑块会每秒调用好几次，
 * 每次都重设 src 会让视频从头开始播）。
 */
function __sparkleApplyBackground(state) {
  var body = document.body;
  if (!body) return;
  var bg = __sparkleBgLayer();
  var kind = state.mediaKind;
  var src = state.mediaUrl || state.dataUrl || '';
  var has = !!(src && kind);
  var fit = state.fit || 'cover';
  var blur = Math.max(0, Math.min(40, Number(state.blur) || 0));
  var dimValue = Math.max(0, Math.min(1, Number(state.dim) || 0));

  bg.root.style.display = has ? 'block' : 'none';
  body.classList.toggle('sparkle-wallpaper', has);
  body.classList.toggle('sparkle-bg-media', has);

  if (!has) {
    if (bg.key) {
      try { bg.video.pause() } catch (e) {}
      bg.video.removeAttribute('src');
      try { bg.video.load() } catch (e) {}
      bg.img.removeAttribute('src');
      bg.tile.style.backgroundImage = '';
      bg.key = '';
    }
    return;
  }

  /* 模糊会让边缘露出一圈透明，放大一点盖住 */
  var scale = blur > 0 ? 1 + blur / 260 : 1;
  bg.stage.style.transform = scale > 1 ? 'scale(' + scale.toFixed(4) + ')' : '';
  bg.stage.style.filter = blur > 0 ? 'blur(' + blur + 'px)' : '';
  bg.dim.style.opacity = String(dimValue);

  var key = kind + '|' + src;
  var isTile = fit === 'tile' && kind === 'image';
  var objectFit = fit === 'contain' ? 'contain' : fit === 'fill' ? 'fill' : 'cover';

  if (key !== bg.key) {
    bg.key = key;
    if (kind === 'video') {
      bg.img.style.display = 'none';
      bg.tile.style.display = 'none';
      bg.video.style.display = 'block';
      bg.video.src = src;
      bg.video.load();
    } else if (isTile) {
      bg.img.style.display = 'none';
      bg.video.style.display = 'none';
      bg.tile.style.display = 'block';
      bg.tile.style.backgroundImage = 'url("' + src + '")';
    } else {
      bg.video.style.display = 'none';
      bg.tile.style.display = 'none';
      bg.img.style.display = 'block';
      bg.img.src = src;
    }
  }

  /* 铺法每次都要更新（tile 与非 tile 之间会切换元素） */
  if (kind === 'image' && isTile) {
    bg.img.style.display = 'none';
    bg.tile.style.display = 'block';
  } else if (kind === 'image') {
    bg.tile.style.display = 'none';
    bg.img.style.display = 'block';
    bg.img.style.objectFit = objectFit;
    /* 从「平铺」切回「铺满」时 src 可能还没设过，这里补上 */
    if (bg.img.getAttribute('src') !== src) bg.img.src = src;
  } else {
    bg.video.style.objectFit = objectFit;
  }

  if (kind === 'video') {
    bg.video.loop = state.videoLoop !== false;
    bg.video.muted = state.videoMuted !== false;
    try { bg.video.playbackRate = Math.max(0.25, Math.min(4, Number(state.videoRate) || 1)) } catch (e) {}
    try {
      var playing = bg.video.play();
      if (playing && playing.catch) playing.catch(function () {});
    } catch (e) {}
  }
}

/* ======================= 3. 外观（背景 + 主题 + 透明度） ======================= */

/** 覆盖原实现：加上主题与背景媒体 */
function __sparkleApplyAppearance(state) {
  if (state && typeof state === 'object') {
    if ('wallpaper' in state) __sparkleLook.wallpaper = state.wallpaper || null;
    if ('mediaPath' in state) __sparkleLook.mediaPath = state.mediaPath || null;
    if ('mediaKind' in state) __sparkleLook.mediaKind = state.mediaKind || null;
    if ('dataUrl' in state) __sparkleLook.dataUrl = state.dataUrl || null;
    if ('mediaUrl' in state) __sparkleLook.mediaUrl = state.mediaUrl || null;
    if ('missing' in state) __sparkleLook.missing = !!state.missing;
    if ('fit' in state) __sparkleLook.fit = state.fit || 'cover';
    if ('blur' in state) __sparkleLook.blur = Number(state.blur) || 0;
    if ('dim' in state) __sparkleLook.dim = Number(state.dim) || 0;
    if ('videoLoop' in state) __sparkleLook.videoLoop = state.videoLoop !== false;
    if ('videoMuted' in state) __sparkleLook.videoMuted = state.videoMuted !== false;
    if ('videoRate' in state) __sparkleLook.videoRate = Number(state.videoRate) || 1;
    if ('themeId' in state) __sparkleLook.themeId = state.themeId || 'default';
    if ('accent' in state) __sparkleLook.accent = state.accent || '';
    if (typeof state.panelOpacity === 'number' && isFinite(state.panelOpacity)) __sparkleLook.panelOpacity = Math.min(1, Math.max(0, state.panelOpacity));
    if (typeof state.editorOpacity === 'number' && isFinite(state.editorOpacity)) __sparkleLook.editorOpacity = Math.min(1, Math.max(0, state.editorOpacity));
  }
  var body = document.body;
  if (!body) return;

  /* 顺序很重要：先落主题变量，下面读 computedStyle 才是新配色 */
  __sparkleApplyAccent(__sparkleLook);

  var cs = null;
  try { cs = getComputedStyle(document.documentElement) } catch (e) { cs = null }
  function pick(name, fb) { var c = cs ? __sparkleParseColor(cs.getPropertyValue(name)) : null; return c || fb }
  var cBg = pick('--bg', { r: 31, g: 31, b: 31 });
  var cElev = pick('--bg-elevated', cBg);
  var cPanel = pick('--bg-panel', cBg);
  var cStatus = pick('--status-bg', cElev);
  var cHover = pick('--hover', { r: 42, g: 45, b: 46 });
  var cActive = pick('--active', { r: 55, g: 55, b: 61 });
  var pa = typeof __sparkleLook.panelOpacity === 'number' ? __sparkleLook.panelOpacity : .72;
  var ea = typeof __sparkleLook.editorOpacity === 'number' ? __sparkleLook.editorOpacity : 1;

  body.style.setProperty('--bg', __sparkleRgba(cBg, pa));
  body.style.setProperty('--bg-elevated', __sparkleRgba(cElev, pa));
  body.style.setProperty('--bg-panel', __sparkleRgba(cPanel, pa));
  body.style.setProperty('--status-bg', __sparkleRgba(cStatus, pa));
  body.style.setProperty('--hover', __sparkleRgba(cHover, pa));
  body.style.setProperty('--active', __sparkleRgba(cActive, pa));
  /* 编辑器底色：Monaco 的容器被 CSS 用 !important 强制成这个变量，所以它必须跟着主题走 */
  body.style.setProperty('--sparkle-editor-bg', __sparkleRgba(cBg, ea));

  var src = __sparkleLook.mediaUrl || __sparkleLook.dataUrl || '';
  var has = !!(src && (__sparkleLook.mediaKind || __sparkleLook.wallpaper));
  var rootEl = document.documentElement;
  rootEl.style.backgroundColor = 'rgb(' + cBg.r + ',' + cBg.g + ',' + cBg.b + ')';
  body.style.backgroundColor = has ? 'transparent' : 'rgb(' + cBg.r + ',' + cBg.g + ',' + cBg.b + ')';
  body.style.backgroundImage = '';
  __sparkleApplyBackground(__sparkleLook);
}

/** 覆盖原实现：背景 / 效果 / 主题 / 透明度 */
function __sparkleAppearanceDialog() {
  if (document.getElementById('sparkle-look-dialog')) return;
  var api = __sparkleLookApi();
  var state = __sparkleLook;

  var mask = __sparkleEl('div', 'position:fixed;inset:0;z-index:4000;background:rgba(0,0,0,.55);display:flex;align-items:flex-start;justify-content:center;padding:8vh 12px;overflow:auto');
  mask.id = 'sparkle-look-dialog';
  var box = __sparkleEl('div', 'width:min(680px,94vw);background:var(--bg-panel,#202020);border:1px solid var(--border,#2b2b2b);border-radius:8px;box-shadow:0 18px 56px rgba(0,0,0,.65);padding:16px 18px 14px;color:var(--fg,#ccc);font-size:12.5px');
  var title = __sparkleEl('div', 'font-size:14px;font-weight:600;margin-bottom:2px');
  title.textContent = '背景与主题';
  var sub = __sparkleEl('div', 'font-size:11.5px;line-height:1.7;color:var(--fg-muted,#6e7681);margin-bottom:14px');
  sub.textContent = '背景支持图片（png / jpg / webp / gif / bmp / avif / svg）和视频（mp4 / webm / ogv / mov / mkv）。视频会循环播放、默认静音。快捷键 Ctrl+Alt+B。';

  function section(name) {
    var wrap = __sparkleEl('div', 'border-top:1px solid var(--border,#2b2b2b);padding:12px 0 4px');
    var h = __sparkleEl('div', 'font-size:12px;font-weight:600;color:var(--fg,#ccc);margin-bottom:10px');
    h.textContent = name;
    wrap.appendChild(h);
    return wrap;
  }
  function line(label, width) {
    var row = __sparkleEl('div', 'display:flex;align-items:center;gap:10px;margin-bottom:10px');
    var name = __sparkleEl('div', 'flex:0 0 ' + (width || 92) + 'px;color:var(--fg-dim,#9d9d9d);font-size:12px');
    name.textContent = label;
    row.appendChild(name);
    return row;
  }
  function slider(value, min, max, step, format, onInput, onDone) {
    var wrap = __sparkleEl('div', 'flex:1 1 auto;display:flex;align-items:center;gap:10px;min-width:0');
    var s = __sparkleEl('input', 'flex:1 1 auto;min-width:0;accent-color:var(--accent,#0078d4);height:16px');
    s.type = 'range'; s.min = String(min); s.max = String(max); s.step = String(step); s.value = String(value);
    var out = __sparkleEl('span', 'flex:0 0 56px;text-align:right;color:var(--fg-dim,#9d9d9d);font-variant-numeric:tabular-nums');
    out.textContent = format(value);
    s.addEventListener('input', function () { var v = Number(s.value); out.textContent = format(v); onInput(v) });
    s.addEventListener('change', function () { var v = Number(s.value); onDone(v) });
    wrap.appendChild(s); wrap.appendChild(out);
    return wrap;
  }
  function select(options, value, onChange) {
    var sel = __sparkleEl('select', 'flex:1 1 auto;min-width:0;font-family:inherit;font-size:12px;padding:5px 8px;border-radius:3px;border:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);color:var(--fg,#ccc);outline:none');
    options.forEach(function (pair) {
      var op = document.createElement('option'); op.value = pair[0]; op.textContent = pair[1]; sel.appendChild(op);
    });
    sel.value = value;
    sel.addEventListener('change', function () { onChange(sel.value) });
    return sel;
  }
  function check(labelText, checked, onChange) {
    var label = __sparkleEl('label', 'display:inline-flex;align-items:center;gap:6px;color:var(--fg-dim,#9d9d9d);font-size:12px;cursor:pointer');
    var cb = document.createElement('input');
    cb.type = 'checkbox'; cb.checked = !!checked;
    cb.style.accentColor = 'var(--accent,#0078d4)';
    cb.addEventListener('change', function () { onChange(cb.checked) });
    label.appendChild(cb); label.appendChild(document.createTextNode(labelText));
    return label;
  }
  function save(patch, rerender) {
    Object.keys(patch).forEach(function (k) { state[k] = patch[k] });
    __sparkleApplyAppearance();
    if (api && api.save) api.save(patch).catch(function () {});
    if (rerender) { refresh(); }
  }

  /* ---- 背景 ---- */
  var secBg = section('背景');
  var fileRow = line('当前背景');
  var fileName = __sparkleEl('div', 'flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--fg-dim,#9d9d9d)');
  var pickBtn = __sparkleBtn('选择图片 / 视频…', '打开一张图片或一段视频作为背景', async function () {
    if (!api) return;
    try {
      var r = await api.pick();
      if (r && r.error) { __sparkleToast(r.error); return; }
      if (r && !r.cancelled) { __sparkleApplyAppearance(r); refresh(); }
    } catch (e) { console.error('选择背景失败：', e) }
  });
  var clearBtn = __sparkleBtn('清除', '去掉背景，恢复纯色', async function () {
    if (!api) return;
    try { var r = await api.clear(); __sparkleApplyAppearance(r); refresh() } catch (e) {}
  });
  fileRow.appendChild(fileName); fileRow.appendChild(pickBtn); fileRow.appendChild(clearBtn);
  secBg.appendChild(fileRow);

  var fitRow = line('铺法');
  var fitSel = select([['cover', '铺满（裁切）'], ['contain', '完整显示'], ['fill', '拉伸填满'], ['tile', '平铺（仅图片）']], state.fit || 'cover', function (v) { save({ fit: v }) });
  fitRow.appendChild(fitSel);
  secBg.appendChild(fitRow);

  var blurRow = line('模糊');
  blurRow.appendChild(slider(Number(state.blur) || 0, 0, 40, 1, function (v) { return v + ' px' }, function (v) {
    state.blur = v; __sparkleApplyAppearance();
  }, function (v) { save({ blur: v }) }));
  secBg.appendChild(blurRow);

  var dimRow = line('压暗');
  dimRow.appendChild(slider(Math.round((Number(state.dim) || 0) * 100), 0, 90, 1, function (v) { return v + '%' }, function (v) {
    state.dim = v / 100; __sparkleApplyAppearance();
  }, function (v) { save({ dim: v / 100 }) }));
  secBg.appendChild(dimRow);

  /* 视频专用设置：只有当前背景是视频时才显示，避免图片用户看到一堆没用的开关 */
  var secVideo = section('视频');
  var loopRow = line('播放');
  loopRow.appendChild(check('循环播放', state.videoLoop !== false, function (v) { save({ videoLoop: v }) }));
  var mutedWrap = __sparkleEl('div', 'margin-left:14px');
  mutedWrap.appendChild(check('静音（推荐）', state.videoMuted !== false, function (v) { save({ videoMuted: v }) }));
  loopRow.appendChild(mutedWrap);
  secVideo.appendChild(loopRow);
  var rateRow = line('倍速');
  rateRow.appendChild(slider(Number(state.videoRate) || 1, .25, 2, .25, function (v) { return v.toFixed(2) + '×' }, function (v) {
    state.videoRate = v; __sparkleApplyAppearance();
  }, function (v) { save({ videoRate: v }) }));
  secVideo.appendChild(rateRow);

  /* ---- 皮肤 ---- */
  var secSkin = section('皮肤');
  var skinNote = __sparkleEl('div', 'font-size:11.5px;line-height:1.7;color:var(--fg-muted,#6e7681);margin-bottom:10px');
  skinNote.textContent = '皮肤是整套外观（配色 + 装饰），会盖掉「设置 → 背景」里的主题，切回「默认」就恢复。所有纹理与光晕都由 CSS 绘制，不含任何游戏素材。';
  secSkin.appendChild(skinNote);

  var skinGrid = __sparkleEl('div', 'display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:12px');
  var skinCards = {};
  __sparkleSkins.forEach(function (sk) {
    var skBg = sk.vars ? sk.vars['--bg'] : '#1f1f1f';
    var skAccent = sk.vars ? sk.vars['--accent'] : '#0078d4';
    var skFg = sk.vars ? sk.vars['--fg'] : '#cccccc';
    var skCard = __sparkleEl('button', 'text-align:left;padding:8px 9px;border-radius:5px;border:1px solid var(--border,#2b2b2b);background:' + skBg + ';color:' + skFg + ';cursor:pointer;font-family:inherit;font-size:11.5px;line-height:1.45;transition:border-color .12s');
    skCard.type = 'button';
    var skDot = __sparkleEl('span', 'display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;vertical-align:-1px;background:' + skAccent);
    skCard.appendChild(skDot);
    skCard.appendChild(document.createTextNode(sk.name));
    var skDesc = __sparkleEl('div', 'font-size:10.5px;opacity:.72;margin-top:3px');
    skDesc.textContent = sk.desc;
    skCard.appendChild(skDesc);
    skCard.addEventListener('click', function () {
      state.skin = sk.id;
      __sparkleApplyAppearance();
      if (api && api.save) api.save({ skin: sk.id }).catch(function () {});
      refresh();
    });
    skinCards[sk.id] = skCard;
    skinGrid.appendChild(skCard);
  });
  secSkin.appendChild(skinGrid);

  /* ---- 主题 ---- */
  var secTheme = section('主题');
  var themeNote = __sparkleEl('div', 'font-size:11.5px;line-height:1.7;color:var(--fg-muted,#6e7681);margin-bottom:10px');
  themeNote.textContent = '跟「设置 → 背景」是同一套设置，在哪边改都会同步。强调色只影响按钮、边框这些高亮，换主题也会保留。';
  secTheme.appendChild(themeNote);

  var grid = __sparkleEl('div', 'display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:12px');
  var themeCards = {};
  var themeRegistry = (typeof na === 'object' && na) ? na : {};
  var themeIds = Object.keys(themeRegistry);
  function currentThemeId() {
    try { return (oa && oa.value && oa.value.theme) || 'dark' } catch (e) { return 'dark' }
  }
  themeIds.forEach(function (id) {
    var t = themeRegistry[id];
    var bg = t.vars['--bg'] || '#1f1f1f';
    var fg = t.vars['--fg'] || '#cccccc';
    var card = __sparkleEl('button', 'text-align:left;padding:8px 9px;border-radius:5px;border:1px solid var(--border,#2b2b2b);background:' + bg + ';color:' + fg + ';cursor:pointer;font-family:inherit;font-size:11.5px;line-height:1.45;transition:border-color .12s');
    card.type = 'button';
    var dot = __sparkleEl('span', 'display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;vertical-align:-1px;background:' + bg + ';border:1px solid ' + (t.vars['--border'] || '#2b2b2b'));
    card.appendChild(dot);
    card.appendChild(document.createTextNode(t.label || id));
    var desc = __sparkleEl('div', 'font-size:10.5px;opacity:.72;margin-top:3px');
    desc.textContent = t.description || '';
    card.appendChild(desc);
    card.addEventListener('click', function () {
      try { fa({ theme: id }) } catch (e) { console.error('切换主题失败：', e) }
      /* fa() 是异步落盘的，等它把变量写上去再重算半透明色 */
      setTimeout(function () { __sparkleApplyAppearance(); refresh() }, 40);
    });
    themeCards[id] = card;
    grid.appendChild(card);
  });
  secTheme.appendChild(grid);

  var accentRow = line('强调色');
  var accentInput = document.createElement('input');
  accentInput.type = 'color';
  accentInput.value = state.accent || '#0078d4';
  accentInput.style.cssText = 'width:38px;height:26px;padding:0;border:1px solid var(--border,#2b2b2b);border-radius:4px;background:transparent;cursor:pointer';
  accentInput.addEventListener('input', function () {
    state.accent = accentInput.value;
    __sparkleApplyAppearance();
  });
  accentInput.addEventListener('change', function () { save({ accent: accentInput.value }) });
  var accentReset = __sparkleBtn('跟随默认', '把强调色恢复成主题默认的蓝色', function () {
    state.accent = '';
    __sparkleApplyAppearance();
    if (api && api.save) api.save({ accent: '' }).catch(function () {});
    refresh();
  });
  accentRow.appendChild(accentInput); accentRow.appendChild(accentReset);
  secTheme.appendChild(accentRow);

  /* ---- 透明度 ---- */
  var secOpacity = section('透明度');
  var panelRow = line('面板');
  panelRow.appendChild(slider(Math.round((Number(state.panelOpacity) || 0) * 100), 0, 100, 1, function (v) { return v + '%' }, function (v) {
    state.panelOpacity = v / 100; __sparkleApplyAppearance();
  }, function (v) { save({ panelOpacity: v / 100 }) }));
  secOpacity.appendChild(panelRow);
  var editorRow = line('编辑器');
  editorRow.appendChild(slider(Math.round((Number(state.editorOpacity) || 0) * 100), 0, 100, 1, function (v) { return v + '%' }, function (v) {
    state.editorOpacity = v / 100; __sparkleApplyAppearance();
  }, function (v) { save({ editorOpacity: v / 100 }) }));
  secOpacity.appendChild(editorRow);
  var opHint = __sparkleEl('div', 'font-size:11.5px;line-height:1.7;color:var(--fg-muted,#6e7681);margin-top:2px');
  opHint.textContent = '面板不透明度越低，背景越明显；编辑器不透明度只影响代码编辑区。';
  secOpacity.appendChild(opHint);

  var foot = __sparkleEl('div', 'display:flex;justify-content:flex-end;gap:8px;border-top:1px solid var(--border,#2b2b2b);padding-top:12px;margin-top:6px');
  var close = __sparkleBtn('关闭', '', function () { if (mask.parentNode) mask.parentNode.removeChild(mask) });
  close.style.padding = '6px 14px'; close.style.fontSize = '12px';
  var exportBtn = __sparkleBtn('导出主题包', '把当前背景、皮肤、透明度存成一个 json 文件', function () {
    var tools = __sparkleToolsApi();
    if (!tools || !tools.exportTheme) return;
    tools.exportTheme().then(function (r) {
      if (r && r.ok) __sparkleToast('已导出到 ' + r.path);
    }).catch(function () {});
  });
  var importBtn = __sparkleBtn('导入主题包', '读取一个 json 主题包并立即应用', function () {
    var tools = __sparkleToolsApi();
    if (!tools || !tools.importTheme) return;
    tools.importTheme().then(function (r) {
      if (r && r.ok) { __sparkleApplyAppearance(r); refresh(); __sparkleToast('主题包已应用'); }
      else if (r && r.error) __sparkleToast(r.error);
    }).catch(function () {});
  });
  foot.appendChild(exportBtn); foot.appendChild(importBtn); foot.appendChild(close);

  box.appendChild(title); box.appendChild(sub);
  box.appendChild(secBg); box.appendChild(secVideo); box.appendChild(secSkin); box.appendChild(secTheme); box.appendChild(secOpacity); box.appendChild(foot);
  mask.appendChild(box);
  mask.addEventListener('keydown', function (ev) { ev.stopPropagation(); if (ev.key === 'Escape') { ev.preventDefault(); if (mask.parentNode) mask.parentNode.removeChild(mask) } });
  mask.addEventListener('keyup', function (ev) { ev.stopPropagation() });
  mask.addEventListener('mousedown', function (ev) { if (ev.target === mask && mask.parentNode) mask.parentNode.removeChild(mask) });
  document.body.appendChild(mask);

  function refresh() {
    var w = state.mediaPath || state.wallpaper || '';
    fileName.textContent = w ? w.split(/[\\/]/).pop() : (state.missing ? '（文件读不到，重新选一个）' : '未设置');
    fileName.title = w || '';
    var isVideo = state.mediaKind === 'video';
    secVideo.style.display = isVideo ? '' : 'none';
    fitSel.value = state.fit || 'cover';
    accentInput.value = state.accent || '#0078d4';
    var activeId = currentThemeId();
    Object.keys(themeCards).forEach(function (id) {
      var active = activeId === id;
      themeCards[id].style.borderColor = active ? 'var(--accent,#0078d4)' : 'var(--border,#2b2b2b)';
      themeCards[id].style.boxShadow = active ? '0 0 0 1px var(--accent,#0078d4) inset' : 'none';
    });
    var activeSkin = state.skin || 'none';
    Object.keys(skinCards).forEach(function (id) {
      var active = activeSkin === id;
      skinCards[id].style.borderColor = active ? 'var(--accent,#0078d4)' : 'var(--border,#2b2b2b)';
      skinCards[id].style.boxShadow = active ? '0 0 0 1px var(--accent,#0078d4) inset' : 'none';
    });
  }
  refresh();
}

/* ======================= 4. C++ 标准与编译参数 ======================= */

var __sparkleCppStdLabel = '';

var __sparkleCppStdOptions = [
  ['', '自动（按编译器版本挑最高可用标准）'],
  ['c++11', 'C++11'],
  ['c++14', 'C++14'],
  ['c++17', 'C++17'],
  ['c++20', 'C++20'],
  ['c++23', 'C++23'],
  ['c++26', 'C++26（需要 GCC 15+）']
];

function __sparkleStdLabelOf(value) {
  if (!value) return '自动';
  return String(value).replace('c++', 'C++');
}

/** 覆盖原实现：多一档 C++26，并且把"当前用的是哪个编译器、它支持到哪"讲清楚 */
function __sparkleBuildConfigDialog() {
  if (__sparkleBuildDialogBusy || document.getElementById('sparkle-build-dialog')) return;
  __sparkleBuildDialogBusy = !0;
  var api = __sparkleBuildApi();
  (async function () {
    var cfg = { cppStandard: '', cflags: '', ldflags: '', runArgs: '' };
    if (api && api.getConfig) {
      try { var got = await api.getConfig(); if (got) cfg = Object.assign(cfg, got) } catch (e) {}
    }
    /* 不在这里 await detect()：首次探测要扫磁盘，可能好几秒，
       对话框会一直不出现。先渲染，再把编译器信息异步填进去。 */
    var compiler = null;
    __sparkleBuildDialogBusy = !1;

    var mask = __sparkleEl('div', 'position:fixed;inset:0;z-index:4000;background:rgba(0,0,0,.55);display:flex;align-items:flex-start;justify-content:center;padding-top:9vh');
    mask.id = 'sparkle-build-dialog';
    var box = __sparkleEl('div', 'width:min(700px,93vw);background:var(--bg-panel,#202020);border:1px solid var(--border,#2b2b2b);border-radius:8px;box-shadow:0 18px 56px rgba(0,0,0,.65);padding:16px 18px 12px;color:var(--fg,#ccc);font-size:12.5px');
    var title = __sparkleEl('div', 'font-size:14px;font-weight:600;margin-bottom:4px');
    title.textContent = 'C++ 标准与编译参数';
    var sub = __sparkleEl('div', 'font-size:11.5px;color:var(--fg-muted,#6e7681);line-height:1.7;margin-bottom:12px');
    sub.textContent = '只影响「编译当前文件 / 编译并运行 / 调试 / 运行」；CMake 项目请直接改 CMakeLists.txt。';

    /* 编译器现状：用户最常问的就是"我到底装的哪个 GCC、能不能用 C++23" */
    var info = __sparkleEl('div', 'display:flex;align-items:center;gap:8px;padding:8px 10px;margin-bottom:12px;border-radius:5px;border:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);font-size:11.5px;line-height:1.6;color:var(--fg-dim,#9d9d9d)');
    info.textContent = '正在读取编译器信息…';
    __sparkleCppStdLabel = __sparkleStdLabelOf(cfg.cppStandard);
    __sparkleRefreshCppBadge();

    function field(label, value, placeholder) {
      var row = __sparkleEl('div', 'display:flex;align-items:center;gap:10px;margin-bottom:10px');
      var name = __sparkleEl('div', 'flex:0 0 92px;color:var(--fg-dim,#9d9d9d);font-size:12px');
      name.textContent = label;
      var input = __sparkleEl('input', 'flex:1 1 auto;min-width:0;font-family:Consolas,"Courier New",monospace;font-size:12px;padding:5px 8px;border-radius:3px;border:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);color:var(--fg,#ccc);outline:none');
      input.type = 'text'; input.spellcheck = !1; input.value = value || ''; input.placeholder = placeholder || '';
      row.appendChild(name); row.appendChild(input);
      return { row: row, input: input };
    }

    var stdRow = __sparkleEl('div', 'display:flex;align-items:center;gap:10px;margin-bottom:10px');
    var stdName = __sparkleEl('div', 'flex:0 0 92px;color:var(--fg-dim,#9d9d9d);font-size:12px');
    stdName.textContent = 'C++ 标准';
    var sel = __sparkleEl('select', 'flex:1 1 auto;min-width:0;font-family:inherit;font-size:12px;padding:5px 8px;border-radius:3px;border:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);color:var(--fg,#ccc);outline:none');
    __sparkleCppStdOptions.forEach(function (pair) {
      var op = document.createElement('option'); op.value = pair[0]; op.textContent = pair[1]; sel.appendChild(op);
    });
    sel.value = cfg.cppStandard || '';
    stdRow.appendChild(stdName); stdRow.appendChild(sel);

    var cf = field('额外编译参数', cfg.cflags, '例如 -I C:/raylib/raylib/src');
    var ld = field('额外链接参数', cfg.ldflags, '例如 -L C:/raylib/raylib/src -lraylib -lopengl32 -lgdi32 -lwinmm');
    var ra = field('运行参数', cfg.runArgs, '例如 --level 3 data.txt（传给程序自己的 argv）');
    var hint = __sparkleEl('div', 'font-size:11.5px;line-height:1.75;color:var(--fg-muted,#6e7681);margin:2px 0 12px');
    hint.textContent = '选「自动」时：GCC 15+ 用 C++26，GCC 14 用 C++23，GCC 11+ 用 C++20，GCC 5+ 用 C++17。手动选高了编译器会报 unrecognized command line option，换低一档即可。';

    var foot = __sparkleEl('div', 'display:flex;align-items:center;gap:8px;justify-content:flex-end');
    var preset = __sparkleBtn('raylib 预设', '填入 raylib 常用参数，路径记得改成你自己的', function () {
      sel.value = 'c++17';
      cf.input.value = '-I C:/raylib/raylib/src';
      ld.input.value = '-L C:/raylib/raylib/src -lraylib -lopengl32 -lgdi32 -lwinmm';
    });
    var save = __sparkleBtn('保存', '保存到用户配置，立刻生效', async function () {
      var payload = { cppStandard: sel.value, cflags: cf.input.value, ldflags: ld.input.value, runArgs: ra.input.value };
      if (!api || !api.setConfig) { save.textContent = '当前版本不支持'; return }
      try {
        await api.setConfig(payload);
        __sparkleCppStdLabel = __sparkleStdLabelOf(payload.cppStandard);
        __sparkleRefreshCppBadge();
        save.textContent = '已保存';
        setTimeout(function () { save.textContent = '保存' }, 1200);
      } catch (e) { save.textContent = '保存失败' }
    });
    save.style.cssText = 'font-family:inherit;font-size:12px;line-height:1;padding:6px 14px;border-radius:3px;border:1px solid var(--accent,#0078d4);background:var(--accent,#0078d4);color:#fff;cursor:pointer';
    var close = __sparkleBtn('关闭', '', function () { if (mask.parentNode) mask.parentNode.removeChild(mask) });
    close.style.padding = '6px 12px'; close.style.fontSize = '12px';
    foot.appendChild(preset); foot.appendChild(close); foot.appendChild(save);

    box.appendChild(title); box.appendChild(sub); box.appendChild(info);
    box.appendChild(stdRow); box.appendChild(cf.row); box.appendChild(ld.row); box.appendChild(ra.row);
    box.appendChild(hint); box.appendChild(foot);
    mask.appendChild(box);
    mask.addEventListener('keydown', function (ev) { ev.stopPropagation(); if (ev.key === 'Escape') { ev.preventDefault(); if (mask.parentNode) mask.parentNode.removeChild(mask) } });
    mask.addEventListener('keyup', function (ev) { ev.stopPropagation() });
    mask.addEventListener('mousedown', function (ev) { if (ev.target === mask && mask.parentNode) mask.parentNode.removeChild(mask) });
    document.body.appendChild(mask);

    /* 编译器信息：探测是异步的，回来后再补，对话框不用等 */
    try {
      window.sparkle.toolchain.detect(false).then(function (tools) {
        var found = (tools || []).filter(function (t) { return t.id === 'gcc' })[0];
        if (!found || !found.available) {
          info.textContent = '还没有可用的 C++ 编译器。到左侧「工具链」面板点「一键下载」，装好 GCC 后回来就能选标准。';
          return;
        }
        var major = parseInt(String(found.version || '0').split('.')[0], 10) || 0;
        var autoStd = major >= 15 ? 'C++26' : major >= 14 ? 'C++23' : major >= 11 ? 'C++20' : major >= 5 ? 'C++17' : major >= 4 ? 'C++14' : 'C++11';
        info.textContent = '当前编译器：' + (found.name || 'GCC') + '（' + (found.path || '') + '）  自动标准：' + autoStd;
      }).catch(function () {
        info.textContent = '读取编译器信息失败，不影响下面的设置。';
      });
    } catch (e) {
      info.textContent = '读取编译器信息失败，不影响下面的设置。';
    }
  })();
}

/** 状态栏那个 "C++ 17" 小徽章：改文字不需要重渲染整个 Vue 树，直接改 DOM 更省事 */
function __sparkleRefreshCppBadge() {
  var btn = document.querySelector('.sparkle-status-btn.cpp');
  if (!btn) return;
  var text = __sparkleCppStdLabel || 'C++ 自动';
  btn.textContent = text;
  btn.title = 'C++ 标准：点一下切换（当前 ' + (__sparkleCppStdLabel || '自动') + '）';
}

function __sparkleInitCppBadge() {
  var api = window.sparkle && window.sparkle.build;
  if (!api || !api.getConfig) return;
  api.getConfig().then(function (cfg) {
    __sparkleCppStdLabel = __sparkleStdLabelOf(cfg && cfg.cppStandard);
    __sparkleRefreshCppBadge();
  }).catch(function () {});
}

