var __sparkleWiki = { root: null, wv: null, current: '', query: '' };

function __sparkleWikiUrl(path) {
  var p = String(path || '').replace(/^\/+/, '');
  return 'https://oi-wiki.org/' + (p ? p.replace(/\/?$/, '/') : '');
}

/** 扁平化，搜索用 */
function __sparkleWikiFlat() {
  if (__sparkleWiki.flat) return __sparkleWiki.flat;
  var out = [];
  __sparkleWikiTopics.forEach(function (g) {
    g.items.forEach(function (it) { out.push({ title: it[0], path: it[1], group: g.group }) });
  });
  __sparkleWiki.flat = out;
  return out;
}

function __sparkleWikiOpen(path, title) {
  var wv = __sparkleWiki.wv;
  if (!wv) return;
  var url = __sparkleWikiUrl(path);
  __sparkleWiki.current = path;
  try { wv.loadURL(url) } catch (e) { wv.setAttribute('src', url) }
  if (title) {
    var crumb = document.getElementById('sparkle-wiki-crumb');
    if (crumb) crumb.textContent = title;
  }
  var items = document.querySelectorAll('.sparkle-wiki-item');
  for (var i = 0; i < items.length; i += 1) {
    items[i].classList.toggle('active', items[i].getAttribute('data-path') === path);
  }
}

function __sparkleWikiToggle(force) {
  var open = typeof force === 'boolean' ? force : !(__sparkleWiki.root && __sparkleWiki.root.style.display !== 'none');
  if (!open) {
    if (__sparkleWiki.root) __sparkleWiki.root.style.display = 'none';
    return;
  }
  __sparkleWikiBuild();
  __sparkleWiki.root.style.display = 'flex';
  var input = document.getElementById('sparkle-wiki-search');
  if (input) setTimeout(function () { input.focus() }, 60);
  if (!__sparkleWiki.current) __sparkleWikiOpen('', 'OI Wiki 首页');
}

function __sparkleWikiBuild() {
  if (__sparkleWiki.root && __sparkleWiki.root.isConnected) return;
  /* 目录项的样子写在一条 <style> 里：hover / active 用内联样式改起来太啰嗦 */
  if (!document.getElementById('sparkle-wiki-style')) {
    var style = document.createElement('style');
    style.id = 'sparkle-wiki-style';
    style.textContent = '.sparkle-wiki-item{display:block;width:100%;text-align:left;padding:5px 12px;border:0;border-left:2px solid transparent;background:transparent;color:var(--fg-dim,#9d9d9d);font-family:inherit;font-size:12px;line-height:1.6;cursor:pointer}.sparkle-wiki-item:hover{background:var(--hover,rgba(255,255,255,.06));color:var(--fg,#ccc)}.sparkle-wiki-item.active{background:var(--active,rgba(255,255,255,.09));color:var(--fg,#ccc);border-left-color:var(--accent,#0078d4)}';
    document.head.appendChild(style);
  }
  var root = document.createElement('div');
  root.id = 'sparkle-wiki-panel';
  root.style.cssText = 'position:fixed;inset:0;z-index:3600;display:none;flex-direction:column;background:var(--bg,#1f1f1f);color:var(--fg,#ccc)';

  /* 顶栏 */
  var bar = document.createElement('div');
  bar.style.cssText = 'flex:none;display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border,#2b2b2b);background:var(--bg-panel,#202020)';
  var logo = document.createElement('div');
  logo.textContent = '📖 OI-Wiki 速查';
  logo.style.cssText = 'font-size:13px;font-weight:600;white-space:nowrap';
  var search = document.createElement('input');
  search.id = 'sparkle-wiki-search';
  search.type = 'text';
  search.spellcheck = false;
  search.placeholder = '搜索目录（回车去官网搜全文）';
  search.style.cssText = 'flex:1 1 auto;min-width:120px;max-width:460px;font-family:inherit;font-size:12.5px;padding:6px 10px;border-radius:4px;border:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);color:var(--fg,#ccc);outline:none';
  var home = __sparkleBtn('首页', '回到 OI Wiki 首页', function () { __sparkleWikiOpen('', 'OI Wiki 首页') });
  var browser = __sparkleBtn('浏览器', '用系统浏览器打开当前页', function () {
    window.open(__sparkleWikiUrl(__sparkleWiki.current), '_blank');
  });
  var close = __sparkleBtn('✕', '关闭（Esc 或 Ctrl+Alt+W）', function () { __sparkleWikiToggle(!1) });
  bar.appendChild(logo); bar.appendChild(search); bar.appendChild(home); bar.appendChild(browser); bar.appendChild(close);

  /* 主体 */
  var bodyWrap = document.createElement('div');
  bodyWrap.style.cssText = 'flex:1 1 0%;display:flex;min-height:0';

  var side = document.createElement('div');
  side.style.cssText = 'flex:0 0 264px;overflow:auto;border-right:1px solid var(--border,#2b2b2b);background:var(--bg-panel,#202020);padding:8px 0 24px';
  var list = document.createElement('div');
  list.id = 'sparkle-wiki-list';
  side.appendChild(list);

  var main = document.createElement('div');
  main.style.cssText = 'flex:1 1 0%;display:flex;flex-direction:column;min-width:0;min-height:0';
  var crumb = document.createElement('div');
  crumb.id = 'sparkle-wiki-crumb';
  crumb.textContent = 'OI Wiki 首页';
  crumb.style.cssText = 'flex:none;padding:5px 12px;font-size:11.5px;color:var(--fg-dim,#9d9d9d);border-bottom:1px solid var(--border,#2b2b2b);background:var(--bg,#1f1f1f);white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
  var wv = document.createElement('webview');
  wv.setAttribute('src', 'https://oi-wiki.org/');
  wv.style.cssText = 'flex:1 1 0%;display:flex;width:100%;min-height:0;border:0;background:#fff';
  main.appendChild(crumb); main.appendChild(wv);

  bodyWrap.appendChild(side); bodyWrap.appendChild(main);
  root.appendChild(bar); root.appendChild(bodyWrap);
  document.body.appendChild(root);

  __sparkleWiki.root = root;
  __sparkleWiki.wv = wv;

  function renderList(filter) {
    list.textContent = '';
    var q = String(filter || '').trim().toLowerCase();
    var flat = __sparkleWikiFlat();
    if (q) {
      var hits = flat.filter(function (it) {
        return it.title.toLowerCase().indexOf(q) >= 0 || it.path.toLowerCase().indexOf(q) >= 0 || it.group.indexOf(q) >= 0;
      });
      var head = document.createElement('div');
      head.textContent = '匹配 ' + hits.length + ' 项';
      head.style.cssText = 'padding:4px 12px 8px;font-size:11px;color:var(--fg-muted,#6e7681)';
      list.appendChild(head);
      if (!hits.length) {
        var empty = document.createElement('div');
        empty.textContent = '目录里没有匹配项，按回车用官网全文搜索。';
        empty.style.cssText = 'padding:6px 12px;font-size:11.5px;line-height:1.7;color:var(--fg-muted,#6e7681)';
        list.appendChild(empty);
      }
      hits.forEach(function (it) { list.appendChild(itemButton(it)) });
      return;
    }
    __sparkleWikiTopics.forEach(function (g) {
      var h = document.createElement('div');
      h.textContent = g.group;
      h.style.cssText = 'padding:10px 12px 5px;font-size:11px;font-weight:600;letter-spacing:.04em;color:var(--fg-muted,#6e7681);text-transform:uppercase';
      list.appendChild(h);
      g.items.forEach(function (it) { list.appendChild(itemButton({ title: it[0], path: it[1], group: g.group })) });
    });
  }

  function itemButton(it) {
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'sparkle-wiki-item';
    btn.setAttribute('data-path', it.path);
    btn.textContent = it.title;
    btn.title = 'oi-wiki.org/' + it.path;
    btn.addEventListener('click', function () { __sparkleWikiOpen(it.path, it.group + ' / ' + it.title) });
    if (it.path === __sparkleWiki.current) btn.classList.add('active');
    return btn;
  }

  search.addEventListener('input', function () { renderList(search.value) });
  search.addEventListener('keydown', function (ev) {
    ev.stopPropagation();
    if (ev.key !== 'Enter') return;
    ev.preventDefault();
    var q = search.value.trim();
    if (!q) return;
    var flat = __sparkleWikiFlat();
    var exact = flat.filter(function (it) { return it.title.toLowerCase() === q.toLowerCase() })[0] || flat.filter(function (it) { return it.title.toLowerCase().indexOf(q.toLowerCase()) >= 0 })[0];
    if (exact) {
      __sparkleWikiOpen(exact.path, exact.group + ' / ' + exact.title);
      return;
    }
    /* 目录里没有 → 交给官网自己的搜索页（MkDocs Material 支持 ?q= 预填） */
    var url = 'https://oi-wiki.org/search/?q=' + encodeURIComponent(q);
    try { wv.loadURL(url) } catch (e) { wv.setAttribute('src', url) }
    crumb.textContent = '官网搜索：' + q;
  });

  /* Esc 关面板：焦点在 webview 里时收不到，所以也允许 Ctrl+Alt+W 兜底 */
  root.addEventListener('keydown', function (ev) {
    if (ev.key === 'Escape') { ev.preventDefault(); __sparkleWikiToggle(false) }
  });

  wv.addEventListener('did-start-loading', function () { crumb.style.opacity = '.55' });
  wv.addEventListener('did-stop-loading', function () { crumb.style.opacity = '1' });
  wv.addEventListener('did-fail-load', function (ev) {
    if (ev && ev.errorCode === -3) return;
    crumb.textContent = '打不开 oi-wiki.org（' + ((ev && ev.errorDescription) || '网络问题') + '）—— 可以点右上角「浏览器」用系统浏览器打开';
  });

  renderList('');
}

/* ======================= 6. 小提示（toast） ======================= */

function __sparkleToast(message) {
  var el = document.getElementById('sparkle-toast');
  if (!el) {
    el = document.createElement('div');
    el.id = 'sparkle-toast';
    el.style.cssText = 'position:fixed;left:50%;bottom:48px;transform:translateX(-50%);z-index:5000;max-width:min(560px,86vw);padding:9px 14px;border-radius:6px;background:var(--bg-panel,#202020);border:1px solid var(--border,#2b2b2b);box-shadow:0 10px 30px rgba(0,0,0,.5);color:var(--fg,#ccc);font-size:12px;line-height:1.6;opacity:0;transition:opacity .18s;pointer-events:none';
    document.body.appendChild(el);
  }
  el.textContent = message;
  el.style.opacity = '1';
  clearTimeout(__sparkleToast.timer);
  __sparkleToast.timer = setTimeout(function () { el.style.opacity = '0' }, 3600);
}

/* ======================= 7. 快捷键与启动 ======================= */

window.addEventListener('keydown', function (ev) {
  if (!(ev.ctrlKey || ev.metaKey) || !ev.altKey || ev.shiftKey) return;
  var key = String(ev.key || '').toLowerCase();
  if (key === 'w') { ev.preventDefault(); __sparkleWikiToggle() }
  else if (key === 'b') { ev.preventDefault(); __sparkleAppearanceDialog() }
});

function __sparklePlusInit() {
  if (!document.body) { setTimeout(__sparklePlusInit, 60); return }
  try { __sparkleBgLayer() } catch (e) { console.error('背景层初始化失败：', e) }
  try { __sparkleCenterInit() } catch (e) { console.error('皮肤样式初始化失败：', e) }
  __sparkleInitCppBadge();
  /* 状态栏是 Vue 渲染的，晚一点才出现；用定时器补一次徽章文字即可 */
  setTimeout(__sparkleRefreshCppBadge, 400);
  setTimeout(__sparkleRefreshCppBadge, 1500);
  setTimeout(__sparkleRefreshCppBadge, 3500);
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', __sparklePlusInit);
else __sparklePlusInit();



